const VERSION = "v7.26.9.24.18 BETA"
class ClientSoundChannel {
    #audioChannel = new VC.AudioChannel();
    #sound = null;
    disposed = false;
    get playing(){
        return !disposed && this.#audioChannel.playing
    }
    performCommand(sound, room){
        if(this.disposed || this.#audioChannel==null || this.#audioChannel.disposed ){
            this.#audioChannel = new VC.AudioChannel();
            this.disposed = false
        }
        this.#sound = sound;
        if(sound.isMusic){
            if(sound.soundCommand==0){
                this.#audioChannel.stop(Music.INDEX[sound.soundId].data);
                return;
            }
            this.#audioChannel.play(
                Music.INDEX[sound.soundId].data,
                .15 * Music.INDEX[sound.soundId].volume,
                true,
                (Date.now() - client.syncTime) - commandTime,
            );
            return;
        }
        if(sound.soundCommand==0 && SoundEffects.INDEX[sound.soundId]){
            this.#audioChannel.stop(SoundEffects.INDEX[sound.soundId].data);
            return;
        }
        if(!this.disposed){
            this.updateVolume (room);
            this.#audioChannel.play(
                SoundEffects.INDEX[sound.soundId].data,
                SoundEffects.INDEX[sound.soundId].volume,
                sound.loop,
                0,
            );
        }
    }
    //updates volume and panning
    updateVolume(room){
        if(this.#sound.isMusic){
            return;
        }
        if(this.#sound.soundCommand == 1){
            if(room.x != this.#sound.room.x || room.y != this.#sound.room.y){
                this.#audioChannel.relativeVolume = Math.abs(room.x - this.#sound.room.x)>1 || Math.abs(room.y - this.#sound.room.y)>1 || (room.x != this.#sound.room.x && room.y != this.#sound.room.y) ? 0 : .66;
                this.#audioChannel.relativePan = this.#sound.room.x < room.x ? -1 : this.#sound.room.x > room.x ? 1 : 0;
            } else if(renderer.currentScene instanceof Level){
                let level = renderer.currentScene;
                
                let gameObject = room.findObjectById(this.#sound.originatorObjectId);
                if(gameObject==null){
                    gameObject = level.findObjectById(this.#sound.originatorObjectId    );
                }
                if(gameObject==null){
                    //console.log("could not find gameobject")
                    this.dispose();
                    return;
                }
                this.#audioChannel.relativeVolume = 1;
                this.#audioChannel.relativePan = -1 + ((gameObject.box.center().x/Renderer.dimensions.width) * 2);   
            }
        }
    }
    dispose(){
        this.#audioChannel.dispose();
        this.disposed=true;
    }
}
class Controller{
    up = 0;
    left = 0;
    down= 0;
    right = 0;
    attack = 0;
    elements = [];
    read(forObject){
        return {
            x: this.left * -1 + this.right,
            y: this.up * -1  + this.down,
            a: this.attack    
        }
    }
    static areEqualReads(read1, read2){
        if(read1 == null && read2 == null){
            return true
        }
        if(read1 == null || read2 == null){
            return false
        }
        if(read1.a != read2.a || read1.x != read2.x || read1.y != read2.y){
            return false;
        }
        return true;
    }
}
class Direction {
    static get NONE(){
        return -1;
    }
    static get NORTH(){
        return 0;
    }
    static get NORTHEAST(){
        return 0.5;
    }
    static get EAST(){
        return 1;
    }
    static get SOUTHEAST(){
        return 1.5;
    }
    static get SOUTH(){
        return 2;
    }
    static get SOUTHWEST(){
        return 2.5;
    }
    static get WEST(){
        return 3;
    }
    static get NORTHWEST(){
        return 3.5;
    }
    static toDegress(direction){
        switch (direction){
            case Direction.EAST:
                return 0;
            case Direction.SOUTHEAST:
                return 45;
            case Direction.SOUTH:
                return 90;
            case Direction.SOUTHWEST:
                return 135;
            case Direction.WEST: 
                return 180;
            case Direction.NORTHWEST:
                return 225;
            case Direction.NORTH:
                return 270;
            case Direction.NORTHEAST:
                return 315;
            default:
                return 0;
        }
    }
}
class Door {
    type = "d"
    level = null;
    room = null;
    wall = 0;
    color = "#4d3737"
    atmosphere = "#000";
    doorFrame = "#928e85";
    barColor = "#707070";
    offset = 0; 
    forceBars = false;
    #elements = [];
    isEntrance = false;
    isExit = false;
    opened = true;
    lock = null;

    constructor(level, room, wall, offset){
        this.level = level;
        this.room = room;
        this.wall = wall % 4;
        this.offset = offset;
    }
    //TODO: Compress Object.
    static fromData(level, room, data){
        let door;
        if(data.t=="s"){
            door = new SecretDoor(level, room, data.w, data.f);
            if(data.g){
                door.poly = VC.Polygon.fromData(data.g);
            }
        }else{
            door = new Door(level, room, data.w, data.f);
        }
        door.setData(data);
        return door;
    }
    setData(data){
        this.offset = data.o;
        this.isEntrance = data.n != null ? data.n : false;
        this.isExit = data.x != null ? data.x : false;
        this.forceBars = data.f != null ? data.f : false;
        this.atmosphere = data.a != null ? data.a : "#000";
        this.color = data.c != null ? data.c : "#4d3737";
        this.box = data.b != null ? VC.Box.fromData(data.b) : null;
        this.opened = data.p;
        this.lock = data.l;
    }

    getData(){
        let data = {
            t: this.type,
            w: this.wall,
            o: this.offset,
        };
        if(this.box){
            data.b = this.box.getData();
        }
        if(this.isEntrance){
            data.n = this.isEntrance;
        }
        if(this.isExit){
            data.x = this.isExit;
        }

        if(this.forceBars){
            data.f = this.forceBars;
        }
        if(this.atmosphere!="#000"){
            data.a = this.atmosphere
        }
        if(this.color!="#4d3737"){
            data.c = this.color
        }
        data.p = this.opened;
        data.l = this.lock;
        return data;
    }

    render(screen){
        if(this.wasOpen != null && this.wasOpen != this.opened && this.opened){
            this.room.playSound(SoundEffects.ROOM_OPENED, false)
        }
        this.wasOpen = this.opened
        focus={};
        focus.x =  (this.wall === Direction.NORTH || this.wall === Direction.SOUTH ? this.room.box.width : this.room.box.height) / 2
        //focus.x = this.room.box.width /2
        focus.y = VC.Trig.cotangent(VC.Trig.degreesToRadians(45)) * focus.x;
    
        let offset={};
        offset.x = 0;//focus.x + this.room.box.x + this.room.wallHeight;
        offset.y = 0;//focus.y + this.room.box.y + this.room.wallHeight + Renderer.dimensions.infoHeight;
    
        //DOOR FRAME
        let x1 = this.offset - constants.doorWidth/2 - constants.doorFrameThickness;
        let y1 = -focus.x;
        let x4 = this.offset + constants.doorWidth/2 + constants.doorFrameThickness;
        let y4 = -focus.x;
        let y2 = y1 - constants.doorHeight - constants.doorFrameThickness;
        let x2 = VC.Trig.cotangent(VC.Trig.pointToAngle(y1,x1)) * y2;
        let y3 = y4 - constants.doorHeight - constants.doorFrameThickness;
        let x3 = VC.Trig.cotangent(VC.Trig.pointToAngle(y4,x4)) * y3;
        this.#elements.push(screen.drawQuad(x1,y1,x2,y2,x3,y3,x4,y4,offset.x,offset.y,this.doorFrame,"#000",constants.lineThickness));
    
    
        //DOOR
        x1 = this.offset - constants.doorWidth / 2;
        y1 = -focus.x;
        x4 = this.offset + constants.doorWidth / 2;
        y4 = -focus.x;
        let dy2 = y1 - constants.doorHeight;
        let dx2 = VC.Trig.cotangent(VC.Trig.pointToAngle(y1,x1)) * dy2;
        let dy3 = y4 - constants.doorHeight;
        let dx3 = VC.Trig.cotangent(VC.Trig.pointToAngle(y4,x4)) * dy3;

        this.#elements.push(screen.drawQuad(x1,y1,dx2,dy2,dx3,dy3,x4,y4,offset.x,offset.y,"#000",0));
        if(this.isEntrance || this.isExit){
            this.#elements.push(screen.drawQuad(x1+10,y1,dx2+10,dy2,dx3-10,dy3,x4-10,y4,offset.x,offset.y,this.atmosphere,0));
        }
        //THRESHOLD
        x1 = this.offset - constants.doorWidth/2 ;
        y1 = -focus.x + constants.lineThickness - 3;
        x4 = this.offset + constants.doorWidth/2;
        y4 = -focus.x + constants.lineThickness - 3;
        y2 = y1 - constants.thresholdDepth;
        if (x1 > 0){
            x2 = VC.Trig.cotangent(VC.Trig.pointToAngle(y1,x1)) * y2;        
        }else {
            x2 = x1 - ((VC.Trig.cotangent(VC.Trig.pointToAngle(y1,x1)) * y2)-x1)/3;
        }
        
        y3 = y4 - constants.thresholdDepth;
        if (x4 < 0){
            x3 = VC.Trig.cotangent(VC.Trig.pointToAngle(y4,x4)) * y3;      
        }else {
            x3 = x4 - ((VC.Trig.cotangent(VC.Trig.pointToAngle(y4,x4)) * y3)-x4)/3;
        }
        this.#elements.push(screen.drawQuad(x1,y1,x2,y2,x3,y3,x4,y4,offset.x,offset.y,"90-" +this.room.palette.floorColor+ ":5-#000:95","#000",0));                
    
        
        if (!this.opened){
            //DOOR
    
            x1 = this.offset - constants.doorWidth / 2;
            y1 = -focus.x - constants.doorFrameThickness;
            x4 = this.offset + constants.doorWidth / 2;
            y4 = -focus.x - constants.doorFrameThickness;
            let dy2 = y1 - constants.doorHeight + constants.doorFrameThickness ;
            let dx2 = VC.Trig.cotangent(VC.Trig.pointToAngle(y1,x1)) * dy2;
            let dy3 = y4 - constants.doorHeight + constants.doorFrameThickness;
            let dx3 = VC.Trig.cotangent(VC.Trig.pointToAngle(y4,x4)) * dy3;
            this.#elements.push(screen.drawQuad(x1,y1,dx2,dy2,dx3,dy3,x4,y4,offset.x,offset.y,this.color,constants.lineThickness));

            
            //KEYHOLE
            let x0 = this.offset;
            let y0 = -focus.x;
            
            y1 = -focus.x - constants.doorHeight/5;
            x1 = (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y1) - constants.doorWidth/12;
            
            y4 = -focus.x - constants.doorHeight/5;
            x4 = (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y1) + constants.doorWidth/12;
    
            y2 = y1 - 16;
            x2 = (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y2) -1 ;        
            y3 = y4 - 16;
            x3 = (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y3) +1; 
    
            this.#elements.push(screen.drawQuad(x1,y1,x2,y2,x3,y3,x4,y4,offset.x,offset.y,"#000","#000",0));
            
            this.#elements.push(screen.drawEllipse( (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y3), y3, 8, 4,offset.x,offset.y,"#000","#000",0));
    
            
        }
    
        if(this.room.barred || this.forceBars){
            let bars = 5;
        
            for(let i=1;i<bars; i++){
                let x0 = (this.offset - constants.doorWidth/2) + (constants.doorWidth/bars) * i;
                let y0 = -focus.x - constants.doorFrameThickness //-this.room.box.width/2;
                let y1 = y0-constants.doorHeight + constants.doorFrameThickness;
                let x1 = (VC.Trig.cotangent(VC.Trig.pointToAngle(y0,x0)) * y1);                    
                
                this.#elements.push(screen.drawLine(x0, y0, x1, y1, "#000", constants.lineThickness*3));
                this.#elements.push(screen.drawLine(x0, y0, x1, y1, this.barColor, constants.lineThickness*2));
                let highlight = screen.drawLine(x0, y0, x1, y1, "#FFF", constants.lineThickness/2)
                highlight.attr({"opacity": .5});
                this.#elements.push(highlight);
                
            }

            
        }
        this.#elements.push(screen.drawLine(dx2, dy2, dx3, dy3, "#000", constants.lineThickness));
        //this.elements.push(screen.drawQuad(x1,y1,x2,y2,x3,y3,x4,y4,offset.x,offset.y,"90-" +this.room.palette.floorColor+ ":5-#000:95","#000",0).attr({"opacity":.5}));                
    
        let t = ""
        switch (this.wall){
            case Direction.NORTH:
                t = "t" + Math.round(focus.x + this.room.box.x) + "," + Math.round(focus.y + this.room.box.y);
                break;
            case Direction.SOUTH:
                t = "r180,0,0t" + Math.round(focus.x + this.room.box.x) *-1+ "," + Math.round(-focus.y + this.room.box.y + this.room.box.height) *-1;
                break;
            case Direction.EAST:
                t = "r90,0,0t" + Math.round(focus.x + this.room.box.y) + "," + Math.round(-focus.y + this.room.box.x + this.room.box.width) * -1;
                break;
            case Direction.WEST:
                t = "r270,0,0t" + Math.round(focus.x + this.room.box.y) * -1 + "," + Math.round(focus.y + this.room.box.x);
                break;
        }      
        this.#elements.forEach((element)=>{
            element.transform(t)
        })
        
        if (DEBUG && this.box ){
            this.box.render(renderer.mainScreen, "#0FF");
        }
        if (DEBUG && this.trip ){
            this.trip.render(renderer.mainScreen, "#F00");
        }
        return this;
    }

    stabilize(){
        let playerBoxHeight = 50;
        let playerBoxWidth = 50;
        switch(this.wall){
            case Direction.NORTH:
                this.box = new VC.Box(
                    this.room.box.x + this.room.box.width / 2 + this.offset - constants.doorWidth/2,
                    this.room.box.y - this.room.wallHeight,
                    constants.doorWidth,
                    this.room.wallHeight + playerBoxHeight * 1.25
                );
                this.trip = new VC.Box(
                    this.room.box.x + this.room.box.width / 2 + this.offset - constants.doorWidth/2,
                    this.room.box.y - playerBoxHeight - 25,
                    constants.doorWidth,
                    playerBoxHeight  
                );
                break;
            case Direction.EAST:
                this.box = new VC.Box(
                    this.room.box.x + this.room.box.width - playerBoxWidth * 1.25,
                    this.room.box.y + this.room.box.height / 2 + this.offset - constants.doorWidth/2,
                    this.room.wallHeight + playerBoxWidth * 1.25,
                    constants.doorWidth
                );
                this.trip = new VC.Box(
                    this.room.box.x + this.room.box.width + 35,
                    this.room.box.y + this.room.box.height / 2 + this.offset - constants.doorWidth/2,
                    playerBoxWidth,
                    constants.doorWidth
                );
                break;
            case Direction.SOUTH:
                this.box = new VC.Box(
                    this.room.box.x + this.room.box.width / 2 - this.offset - constants.doorWidth/2,
                    this.room.box.y + this.room.box.height - this.room.wallHeight,
                    constants.doorWidth,
                    this.room.wallHeight + playerBoxHeight * 1.25
                );
                this.trip = new VC.Box(
                    this.room.box.x + this.room.box.width / 2 - this.offset - constants.doorWidth/2,
                    this.room.box.y + this.room.box.height + 35,
                    constants.doorWidth,
                    playerBoxHeight  
                );
                break;
            case Direction.WEST:
                this.box = new VC.Box(
                    this.room.box.x - this.room.wallHeight,
                    this.room.box.y + this.room.box.height / 2 - this.offset - constants.doorWidth/2,
                    this.room.wallHeight + playerBoxWidth * 1.25,
                    constants.doorWidth
                );
                this.trip = new VC.Box(
                    this.room.box.x - this.room.wallHeight,
                    this.room.box.y + this.room.box.height / 2 - this.offset - constants.doorWidth/2,
                    playerBoxWidth,
                    constants.doorWidth
                );
                break;
            default:
                console.warn({"unexpected wall": wall});  
        }
    }

    contains(box){
        this.init();
        if(this.portalTo){
            this.opened = this.portalTo.opened;
        }
        if(box && box instanceof VC.Box && this.opened && !this.forceBars && !this.room.barred){
            return box.inside(this.box);
        }
        return false; 
    }

    remove(){
        this.#elements.forEach((e)=>{e.remove()});
        this.#elements = [];
    }
}
class Floor {
    static _tiles = []; 
    type = "OVERRIDE ME";

    _seed = Math.floor(Math.random()*100);
    _minX = null;
    _maxX = null;
    _minY = null;
    _maxY = null;
    
    constructor(){
        if (Floor._tiles.length === 0) {
            for(let i=0; i<100; i++){
                switch(Math.round(Math.random()*7)%7){
                    case 0:
                        Floor._tiles.push("#555555");
                    case 1:
                        Floor._tiles.push("#565656");
                    case 2:
                        Floor._tiles.push("#646464");
                    case 3:
                        Floor._tiles.push("#545454");
                    case 4:
                        Floor._tiles.push("#575454");
                    case 5:
                        Floor._tiles.push("#545457");
                    case 6:
                        Floor._tiles.push("#545754");
                }
            }
        }
    }

    static fromData(data){
        switch (data.t){
            case "r":
                return RectangularTileFloor.fromData(data);
            case "h":
                return HexagonalTileFloor.fromData(data);
            case "n":
                return NoiseFloor.fromData(data);
        }
    }

    render(roomBounds){
        if(!(roomBounds instanceof VC.Polygon)){
            throw ("roomBounds must be VC.Polygon")
        }
        
        //square the polygon
        
        this._minX = null;
        this._maxX = null;
        this._minY = null;
        this._maxY = null;
        
        roomBounds.points.forEach(p => {
            if(this._minX == null || p.x < this._minX){
                this._minX = p.x;
            }
            if(this._maxX == null || p.x > this._maxX){
                this._maxX = p.x;
            }
            if(this._minY == null || p.y < this._minY){
                this._minY = p.y;
            }
            if(this._maxY == null || p.y > this._maxY){
                this._maxY = p.y;
            }
        });
    }

    remove(){
    }
}
class Format {
    static numberWithCommas(number) {
        return Math.round(number).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    }

    static msToTime(duration) {
        let milliseconds = Math.floor((duration % 1000) / 100),
          seconds = Math.floor((duration / 1000) % 60),
          minutes = Math.floor((duration / (1000 * 60)) % 60),
          hours = Math.floor((duration / (1000 * 60 * 60)));
      
        hours = hours > 0 ? ((hours < 10) ? "0" + hours + ":" : hours + ":") : "";
        minutes = (minutes < 10) ? "0" + minutes : minutes;
        seconds = (seconds < 10) ? "0" + seconds : seconds;
      
        return hours + minutes + ":" + seconds + "." + milliseconds;
    }
}
class GameLauncher {
    static launchSinglePlayer(){
        server = new Server();
        game = new Game(server);
        game.setFrameLimit(60);
        const [serverSide, clientSide] = VC.LoopbackConnection.createPair();
        serverSide.metadata = client.id;
        clientSide.metadata = client.id;
        server.addConnection(serverSide);
        client.attach(clientSide);
        game.currentScene = new LevelSelectScreen();
        game.play();
    }

    static startHost(){
        server = new Server();
        game = new Game(server);
        game.currentScene = new LobbyScreen();
        game.setFrameLimit(30);
        const [serverSide, clientSide] = VC.LoopbackConnection.createPair();
        serverSide.metadata = client.id;
        clientSide.metadata = client.id;
        server.addConnection(serverSide);
        client.attach(clientSide);
        server.startHost();
        game.play();
    }
}
class GlyphButton {

    static glyphColor = "#FFF";
    static borderColor = "#ffd700";

    leftGlyph = null;
    rightGlyph = null;
    aboveGlyph = null;
    belowGlyph = null;    
    elements=[]

    selected = false;

    screenText = "";
    value = null;
    x = 0;
    y = 0;
    width = 0;
    height = 0;

    structureRendered = false;
    elements = [];

    constructor(screenText, value, x, y, width, height){
        this.screenText = screenText;
        this.value = value;
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }

    render(screen){
        if(!this.structureRendered){
            let text = screen.text(this.x, this.y, this.screenText)
            
            text.attr({ "font-size": "48px", "font-family": "monospace", "font-weight":"bold", "fill": GlyphButton.glyphColor});
            this.elements.push(text);
            let x = this.x-this.width/2;
            let y = this.y-this.height/2;
            
            //border
            this.elements.push(screen.drawLine(x, y, x + this.height/4, y, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x, y, x, y + this.height/4, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x, y+this.height, x + this.height/4, y+this.height, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x, y+this.height, x, y+this.height - + this.height/4, GlyphButton.borderColor, 5));

            this.elements.push(screen.drawLine(x + this.width, y, x + this.width - this.height/4, y, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x + this.width, y, x + this.width, y + this.height/4, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x + this.width, y+this.height, x + this.width - this.height/4, y+this.height, GlyphButton.borderColor, 5));
            this.elements.push(screen.drawLine(x + this.width, y+this.height, x + this.width, y+this.height - + this.height/4, GlyphButton.borderColor, 5));

            this.structureRendered = true;
        }

        this.elements.forEach((e,i)=>{e.attr({"opacity":this.selected||i==0 ? 1 : 0})});
    }
}
