class Player {
    gameObject = null;
    playerName = "";
    clientId = "";
    #spectating = "";
    lastSceneName = "";
    controller = null;
    levelState = [2,2,2,2,2];
    playTime = 0;

    get spectating(){
        if(this.#spectating == null || this.#spectating == ""){
            return this.clientId;
        }
        return this.#spectating;
    }
    set spectating(value){
        this.#spectating = value;
    }

    getData(){
        let data = {
            i: this.clientId,
            s: this.spectating,
            n: this.playerName
        };
        if(this.gameObject){
            data.o = this.gameObject.id;
            if(this.gameObject.room){
                data.r = this.gameObject.room.id;
            }
        }
        else{
            //console.error("no gameobject!!!")
        }
        return data;
    }
    static fromData(data){
        if(data && data.i){
            let result = new Player()
            result.clientId = data.i;
            result.spectating = data.s;
            result.setData(data);
            return result
        }
        return null;
    }

    setData(data){
        if(data.i == this.clientId){
            this.playerName = data.n;
            this.spectating = data.s;
            if((!this.roomFound) || data.o && (!this.gameObject || data.o!=this.gameObject.id || this.gameObject.room==null || (!isNaN(data.r) && this.lastRoom && this.lastRoom.id != data.r))){
                if(renderer.currentScene instanceof Level){
                    //console.log("finding game object")
                    if(renderer.currentScene instanceof Level){
                        if(!isNaN(data.r)){
                            let room = renderer.currentScene.findRoomById(data.r);
                            if (room){
                                this.gameObject = room.findObjectById(data.o);    
                                this.roomFound==true;      
                            }else{
                                this.roomFound==false;
                            }
                            this.lastRoom  = room
                            //this.lastRoom = this.gameObject && this.gameObject.room ? this.gameObject.room : null;
                        } else if (this.gameObject && this.gameObject.health <=0 && isNaN(data.r)){
                            this.gameObject.room = null;
                        }
                    }

                }else if(renderer.currentScene instanceof EndLevelSummary){
                    this.gameObject = renderer.currentScene.findObjectById(data.o);
                    this.lastRoom = this.gameObject && this.gameObject.room ? this.gameObject.room : null;
                    if(this.lastRoom == null){
                        console.log("lastroom is null!")
                    }
                }
        
            } else if (!data.o){
                this.gameObject = null;
                this.lastRoom = null;
                //console.log("removing game object!!")
            }else {
                //console.log("something's borken", data.o, this.gameObject.id, this.gameObject.room ? this.gameObject.room.id : "MISSING")
            }
        }
        
    }
}
class SceneManager {
    static CreateScene(sceneName){
        switch (sceneName){
            case "ts":
                return new TitleScreen();
            case "ss":
                return new SlotSelectScreen();
            case "ls":
                return new LevelSelectScreen();
            case "go":
                return new GameOverScreen();
            case "gm":
                return new GameModeScreen();
            case "el":
                return new EndLevelSummary();
            case "ew":
                return new EndWorldScreen();
            case "lb":
                return new LobbyScreen();
            case "l":
                return new Level();
            default:
                console.warn("unexpected scene name:", sceneName)
                return null; 
        }
    }
}

class Sound {
    static idCounter = 0;
    eventId = 0;
    //source
    room = new VC.Point(); // x, y on map
    originatorObjectId = 0; // used to get x, y in room, and to stop the sound of the object disappears
    channelId = 0; //used if the object needs multple channels. 
    soundId = 0;
    soundCommand = 1; //1 = play; 0 = stop
    commandTime = 0; // the gameTime (from syncTime) of the loop

    /*Looping Vars: experiment with these for short-lived sounds(whip, explosions, etc.)*/
    loop = false; // whether the sound should be looped or not
    isMusic = false; //whether the id refers to a music id or sound effect id.

    constructor(room, objectId, channelId, soundId, soundCommand, loop, isMusic, eventId){
        if(eventId){
            this.eventId = eventId
        }else {
            this.eventId = Sound.idCounter++;
        }
        this.room = new VC.Point(room.x, room.y);
        this.originatorObjectId = objectId; 
        this.channelId = channelId;
        this.soundId = soundId;
        this.soundCommand = soundCommand;
        this.loop = loop == null ? false : loop;
        this.isMusic = isMusic == null ? false : isMusic;
        this.commandTime = Date.now() - (server && server.syncTime ? server.syncTime : client.syncTime)
    }

    getData(){
        let data = {
            e: this.eventId,
            r: {x:this.room.x, y:this.room.y},
            o: this.originatorObjectId,
            c: this.channelId,
            s: this.soundId,
            p: this.soundCommand,
            t: this.commandTime
        }
        if(this.loop){
            data.l = this.loop;
        }
        if(this.isMusic){
            data.m = this.isMusic;
        }
        return data;
    }
    static fromData(data){
        if(!data || data.r == null || data.o == null || data.c == null || data.p == null || data.s == null || data.t == null){
           throw("cannot create sound from provided data:", data)
        }
        let sound = new Sound(
            data.r,
            data.o,
            data.c,
            data.s,
            data.p,
            data.l ? data.l : false,
            data.m ? data.m : false,
            data.e
        )
        sound.commandTime = data.t;
        return sound;
    }
}
