class Temple{
    
    constructor(){
    
    }
    themeLevel(level){
        
    }

    themeRoom(room, index){
        
    }
    
    
    static addTorches(level){
        //Add torches
        level.rooms.forEach((room)=>{
            for(let wall = Direction.NORTH; wall<=Direction.WEST; wall++){
                let wallDoor = room.findDoor(wall);
                if(wallDoor == null){
                    let torch = new Torch(room);
                    switch(wall){
                        case Direction.NORTH:
                            torch.box.x = room.box.center().x;
                            torch.box.y =  room.box.y - room.wallHeight/2;
                            torch.wall = wall;
                            break;
                        case Direction.EAST:
                            torch.box.x = room.box.x + room.box.width + room.wallHeight/2; 
                            torch.box.y = room.box.center().y;
                            torch.wall = wall;
                            break;
                        case Direction.SOUTH:
                            torch.box.x = room.box.center().x;
                            torch.box.y =  room.box.y + room.box.height + room.wallHeight/2;
                            torch.wall = wall;
                            break;
                        case Direction.WEST:
                            torch.box.x = room.box.x - room.wallHeight/2; 
                            torch.box.y =  room.box.center().y;
                            torch.wall = wall;
                            break;
                    }
                }
            }
        })
    }
}
function right(str,chr)
{
    return str.substr(str.length-chr,str.length)
}

function randomEntry(array){
    if(array.length === 0){
        return null;
    }
    let index =  Math.floor((array.length-1) * Math.random());
    return array[index]; 
}

function filter(array, fun){
    let array2 = [];
    array.forEach((item)=>{
        if(fun(item)){
            array2.push(item);
        }
    })
    return array2;
}

function log(...args){
    if(DEBUG){
        console.log(...args);
    }
}

function remove(array, fun){
    let itemsToDelete = filter(array,fun);
    itemsToDelete.forEach((item)=>{
        array.splice(array.indexOf(item),1);
    });
}

function any(array, fun){
    if(!array){
        return false;
    }
    for(let i=0;i<array.length; i++){
        if(fun(array[i], i)){
            return true;
        }
    }
    return false;
}

function all(array, fun){
    if(!array){
        return false;
    }
    for(let i=0;i<array.length; i++){
        if(!fun(array[i], i)){
            return false;
        }
    }
    return true;
}

function minValue(array, fun){
    if(!array){
        return null
    }
    let m = null;
    let val = null;
    for(let i=0;i<array.length; i++){
        let calc = fun(array[i]);
        if(m == null || calc < m){
            m = calc;
            val = array[i];
        }
    }
    return val;
}

function maxValue(array, fun){
    if(!array){
        return null
    }
    let m = null;
    let val = null;
    for(let i=0;i<array.length; i++){
        let calc = fun(array[i]);
        if(m == null || calc > m){
            m = calc;
            val = array[i];
        }
    }
    return val;
}

function isPlayer(gameObject){
    return gameObject instanceof Adventurer; //&& server.players.has(gameObject.id);
}

function regionColor(region){
    switch (region){
        case Treasure.SILVERKEY:
            return "#606060";
        case Treasure.GOLDKEY:
            return "#997700";
        case Treasure.REDKEY:
            return "#600000";
        case Treasure.GREENKEY: 
            return "#006000";
        case Treasure.BLUEKEY: 
            return "#000070";
    }
    return "#864";
}

function playMusic(url){
    if(url==renderer.lastMusic){
        return;
    }
    //to keep music in sync, start at the exact same moment.
    //assumes clocks are in sync across devices... 
    let now = Date.now();
    let roundDown = Math.floor(now/1000)*1000;
    if(roundDown<now){
        roundDown += 2500;//add about two seconds
        setTimeout(renderer.playMusic(url), roundDown-Date.now());
    }
}


