class AutoController extends Controller {
    #reverseInput = false;
    get reverseInput(){
        return this.#reverseInput;
    }
    set reverseInput(value){
        this.#reverseInput = value;
    }

    constructor(){
        super()
    }

    read(forObject){
        this.attack = 0;
        let opposingTeam = Team.getOpposingTeam(forObject.team);
        if(!forObject.blindUntil || forObject.blindUntil<Date.now()){
            forObject.getObjectsInRangeOfAttack().forEach((o)=>{
                if(o.team === opposingTeam && !o.hidden){
                    this.attack = 1; 
                }
            });
        }
        if(this.attack === 0){
            //initialize autocontroller settings
            let now = Date.now();
            let ac = null;
            if(forObject.ac){
                ac = forObject.ac;
            }else {
                ac = {};
                forObject.ac = ac;
                ac.nextRetarget = now;
                ac.nextDirection = now;
                ac.primaryTarget = null;
                ac.secondaryTarget = null;
                ac.lastPos = forObject.box.center();
            }

            if(DEBUG){
                if(ac.primaryTarget) ac.primaryTarget.remove();
                if(ac.secondaryTarget) ac.secondaryTarget.remove();
            }
            
            if(forObject.box.containsPoint(ac.secondaryTarget) || (ac.lastPos.x == forObject.box.center().x && ac.lastPos.y == forObject.box.center().y)){
                ac.nextRetarget = now;
                ac.secondaryTarget = null;
            }
            ac.lastPos = forObject.box.center();
            if(ac.nextRetarget<=now){
                ac.nextRetarget = Date.now() + 750;//play with this
                //find the closest enemy. 

                let viewableEnemies = forObject.getObjectsInView().filter((obj)=>obj.team===opposingTeam && obj.state!=State.DEAD);
                ac.primaryTarget = null;
                viewableEnemies.forEach((e)=>{
                    if(ac.primaryTarget==null || ac.primaryTarget.distanceTo(forObject.box.center())>e.box.center().distanceTo(forObject.box.center())){
                        ac.primaryTarget = e.box.center();
                    }
                });

                if(VC.Math.random(0,9)==0 && forObject.transferrable && game.level){
                    //send to player
                    game.level.players.forEach((player)=>{
                        if(player.gameObject && player.gameObject.room && !player.gameObject.room.barred){
                            forObject.room.doors.forEach((d)=>{
                                if(d.opened && game.level.findNeighbor(forObject.room,d.wall)===player.room){
                                    ac.secondaryTarget = d.trip.center();
                                }
                            });
                        }
                    });
                }

                while(ac.secondaryTarget == null){
                    ac.secondaryTarget = new VC.Point(
                        VC.Math.random(forObject.room.box.x, forObject.room.box.x + forObject.room.box.width),
                        VC.Math.random(forObject.room.box.y, forObject.room.box.y + forObject.room.box.height)
                    )
                    if(!forObject.room.bounds.containsPoint(ac.secondaryTarget) || any(forObject.room.objects, (o)=>{
                        if(!(o instanceof Character) && (o.plane == Plane.PHYSICAL || o instanceof LavaPool) && o.bounds.containsPoint(ac.secondaryTarget)){
                            return true;
                        }
                        return false;
                    })){ // sanity check
                        ac.secondaryTarget = null //try again
                    }
                }
            }

            let target = ac.primaryTarget ? ac.primaryTarget : ac.secondaryTarget;
            let directed = false;
            if (target!=null && ac.nextDirection<=now){
                ac.nextDirection = now + 750;
                let angle = VC.Trig.pointToAngle(target.y - forObject.box.center().y, target.x - forObject.box.center().x);
                let deg = VC.Trig.radiansToDegrees(angle);
                if (deg <0) {   
                    deg += 360
                }
                if (deg>=22.5 && deg<67.5){
                    this.right = 1;
                    this.down = 1;
                    this.left = 0;
                    this.up = 0;
                }else if (deg>=67.5 && deg<112.5){
                    this.right = 0;
                    this.down = 1;
                    this.left = 0;
                    this.up = 0;
                }else if (deg>=112.5 && deg<157.5){
                    this.right = 0;
                    this.down = 1;
                    this.left = 1;
                    this.up = 0;
                } else if (deg>=157.5 && deg<202.5){
                    this.right = 0;
                    this.down = 0;
                    this.left = 1;
                    this.up = 0;
                } else if (deg>=202.5 && deg<247.5){
                    this.right = 0;
                    this.down = 0;
                    this.left = 1;
                    this.up = 1;
                } else if (deg>=247.5 && deg<292.5){
                    this.right = 0;
                    this.down = 0;
                    this.left = 0;
                    this.up = 1;
                } else if (deg>=292.5 && deg<337.5){   
                    this.right = 1;
                    this.down = 0;
                    this.left = 0;
                    this.up = 1;
                } else {
                    this.right = 1;
                    this.down = 0;
                    this.left = 0;
                    this.up = 0;  
                }
                directed = true
            }

            if(directed && !(forObject instanceof Bat)){
                let nvBoxScale=1.25;

                let navigationBox = new VC.Box(
                    forObject.box.center().x - (forObject.box.width * nvBoxScale / 2),
                    forObject.box.center().y - (forObject.box.height * nvBoxScale / 2),
                    forObject.box.width * nvBoxScale,
                    forObject.box.height * nvBoxScale
                );
                switch(forObject.direction){
                    case Direction.NORTH:
                        navigationBox.y -= navigationBox.height/2;
                        break;
                    case Direction.EAST:
                        navigationBox.x += navigationBox.width/2;
                        break;
                    case Direction.SOUTH:
                        navigationBox.y += navigationBox.height/2;
                        break;
                    case Direction.WEST:
                        navigationBox.x -= navigationBox.width/2;
                        break;
                }

                let correctedCourse = false

                forObject.getObjectsInView().forEach((o)=>{
                    if(o!=forObject && navigationBox.collidesWith(o.box) || (o instanceof LavaPool && o.polygon.collidesWith(navigationBox.polygon))){
                        if((o.plane === Plane.PHYSICAL && o.team!=opposingTeam) || o instanceof LavaPool){
                            correctedCourse = true;
                            if(this.up && o.box.center().y < navigationBox.center().y){
                                if(target.x<o.box.center().x){
                                    this.left = 1;
                                } else {
                                    this.right = 1;
                                }
                                this.up = 1;
                            } else if (this.down && o.box.center().y > navigationBox.center().y){
                                if(target.x<o.box.center().x){
                                    this.left = 1;
                                } else {
                                    this.right = 1;
                                }
                                this.down = 1;
                            } else if(this.left && o.box.center().x < navigationBox.center().x){
                                if(target.y<o.box.center().y){
                                    this.up = 1;
                                } else {
                                    this.down = 1;
                                }
                                this.left = 1;
                            } else if(this.right && o.box.center().x > navigationBox.center().x){
                                if(target.y<o.box.center().y){
                                    this.up = 1;
                                } else {
                                    this.down = 1;
                                }
                                this.right = 1;
                            }
                        }
                    }
                });
                
               
                if (!correctedCourse){
                    if(!Room.contains(forObject.room, forObject, navigationBox)){
                        if(this.up){
                            if(target.x<forObject.box.center().x){
                                this.left = 1;
                            } else {
                                this.right = 1;
                            }
                            this.up = 1;
                        } else if (this.down){
                            if(target.x<forObject.box.center().x){
                                this.left = 1;
                            } else {
                                this.right = 1;
                            }
                            this.down = 1;
                        } else if(this.left){
                            if(target.y<forObject.box.center().y){
                                this.up = 1;
                            } else {
                                this.down = 1;
                            }
                            this.left = 1;
                        } else if(this.right){
                            if(target.y<forObject.box.center().y){
                                this.up = 1;
                            } else {
                                this.down = 1;
                            }
                            this.right = 1;
                        }
                        correctedCourse = true;
                    }
                }
    
            }
/*
            if(DEBUG && forObject.room == game.level.currentRoom){
                if(ac.primaryTarget) ac.primaryTarget.render(game.screen, "#F00");
                if(ac.secondaryTarget) ac.secondaryTarget.render(game.screen, "#4F4");
            }
                */
        }
        return {
            x: (this.left * -1 + this.right) * (this.#reverseInput ? -1 : 1),
            y: (this.up * -1 + this.down) * (this.#reverseInput ? -1 : 1),
            a: this.attack
        }
    }
}
class GameObject{
    static idCounter = 0;
    code = "ERROR";
    box = new VC.Box(0,0,50,50);
    z = 0;
    reflectElements = [];
    direction = Direction.NORTH;
    layer = Layer.DEFAULT;
    plane = Plane.PHYSICAL;
    team = Team.UNALIGNED;
    _stateStart =  Date.now();
    _lastAttack =  new Date(0);
    #removed = false;
    #room = null;
    immovable = false;
    transferrable = true;
    sync = true;
    clearRegistered = false;

    getData(){
        //log(this.tag, this.id);
        if(this.code == 'adv'){
            //log(this.code, "room is", this.room ? this.room.id : "")
        }
        return {
            id: this.id, 
            c: this.code,
            b: this.box.getData(),
            d: this.direction,
            s: this.state,
            st: this._stateStart,
            r: this.room ? this.room.id : "",
            z: this.z
        }
        
    }
    setData(data) {
        if(data && this.id == data.id){
            //log("setting", data)
            this.box.reset(data.b.x, data.b.y, data.b.w, data.b.h);
            //log(this.tag, this.id, this.box);
            this.state = data.s;
            this._stateStart = data.st;
            if(!this.room || this.room.id != data.r){
                //console.log("setting room")
                this.room = renderer.currentScene instanceof Level ? renderer.currentScene.findRoomById(data.r) : renderer.currentScene instanceof EndLevelSummary ? renderer.currentScene : null;
                //console.warn(this.code, "room not found:", data.r)
            }
            
            this.z = data.z;
            this.direction = data.d;
        }
    }
    static fromData(data, room){
        let go;
        //let room = renderer.currentScene instanceof Level ? renderer.currentScene.findRoomById(data.r) : renderer.currentScene instanceof EndLevelSummary ? renderer.currentScene : null;

        if(room){
            switch(data.c){
                case "adv":
                    go = new Adventurer(room, null);
                    break;
                case "bat":
                    go = new Bat(room, null);
                    break;
                case "crb":
                    go = new Crabman(room, null);
                    break;
                case "glm":
                    go = new CharcoalGolem(room, null);
                    break;
                case "mns":
                    go = new Manos(room, null);
                    break;
                case "msk":
                    go = new MaceSkeleton(room, null);
                    break;
                case "rat":
                    go = new Rat(room, null);
                    break;
                case "spi":
                    go = new CaveSpider(room, null);
                    break;
                case "snk":
                    go = new Snake(room, null);
                    break;
                case "ssk":
                    go = new SwordSkeleton(room, null);
                    break;
                case "ex":
                    go = new Exit(room);
                    break;
                case "fb":
                    go = new Fireball(room);
                    break;
                case "fe":
                    go = new FireballExplosion(room);
                    break;
                case "if":
                    go = new InfernusFireball(room);
                    break;
                case "io":
                    go = new InvisibleObject(room);
                    break;
                case "lp":
                    go = new LavaPool(room);
                    break;
                case "mb":
                    go = new ManosBlock(room);
                    break;
                case "pu":
                    go = new Pickup(room);
                    break;
                case "sc":
                    go = new ScorchMark(room);
                    break;
                case "sm":
                    go = new SmokeBillow(room);
                    break;
                case "st":
                    go = new SpikeTrap(room);
                    break;
                case "sb":
                    go = new Starburst(room);
                    break;
                case "tc":
                    go = new TreasureChest(room);
                    break;
                case "tn":
                    go = new TNT(room);
                    break;
                case "tx":
                    go = new Torch(room);
                    break;
                case "vn":
                    go = new Vine(room);
                    break;
                case "xp":
                    go = new Explosion(room);
                    break;
                case "wp":
                    go = new WaterPool(room);
                    break;
                default:
                    console.warn("unexpected code: " + data.c)
            }
            if(go){
                go.id = data.id;
                go.room = room;
                go.setData(data);
            }
        }else{
            console.warn("no room with id ", data.r, "; failed to create", data.c)
        }
        return go;
    }

    constructor(room){
        this.id = GameObject.idCounter++;
        //log(room)
        if(room==null && (this.constructor.name != "TNT")){
            if(game){
               console.warn("room required");
            }
        }
        this.room = room;
    }

    get room(){
        return this.#room;
    }

    set room(nextRoom){
        if(nextRoom == this.#room){
            return
        }
        if (this.#room ){
            let currentIndex = this.#room.objects.indexOf(this);
            if (currentIndex>-1){
                this.#room.objects.splice(currentIndex, 1);
            }
        }
       
        this.#room = nextRoom;
        if(!nextRoom){
            //console.warn(this.code, "next room is null!!!!")
        }
        if(nextRoom){
            if(this.#room ){
                this.#room.objects.push(this);
                if(this.sprite){
                    this.sprite.fadeIn(250);
                }
            }
        }
    }

    #state = State.IDLE
    get state() {
        return this.#state;
    }
    set state(value){
        if (value!==this.#state){
            this.#state = value;
            this._stateStart = Date.now();
            if(this.state===State.ATTACKING){
                this._lastAttack = Date.now();
            }
        }
    }

    get bounds(){
        if(this.perimeter){
            if(!this.perimeterBox){
                this.perimeterBox = new VC.Box(0,0,this.perimeter, this.perimeter);
            }
            this.perimeterBox.center(this.box.center())
            return this.perimeterBox;
        }
        return this.box;
    }
    
    /*
    //TODO: Fix for panning rooms
    checkAudioLevels(){
        let relativePan = 0;
        let relativeVolume = 1;
        if (game && game.level && game.level.currentRoom === this.room){
            relativePan = -1 + ((this.box.center().x/dimensions.width) * 2);
            relativeVolume = this.room.volume;
        } else if (this.room && this.room!=game.currentRoom && this instanceof Character){
            if(!this.room.opened){
                relativeVolume = .33;
            }else {

                relativePan = this.room.volume;
                let maxDistance = 500;
                this.room.doors.forEach((d)=>{
                    if(game && game.level && game.level.findNeighbor(this.room,d.wall)===game.level.currentRoom){
                        let dist = this.box.center().distanceTo(d.trip.center())
                        dist = VC.Math.constrain(0, dist, maxDistance);
                        relativeVolume =  VC.Math.inversePercentToRange(dist/maxDistance, this.room.volume * .33, this.room.volume);
                    }
                })  
            }
            relativePan = this.room.pan;
        } else if (this.room){
            relativePan = this.room.pan;
            relativeVolume = this.room.volume;
        } else if (this.room == null){ //TNT, Held by player
            relativePan = -1 + ((this.box.center().x/Renderer.dimensions.width) * 2);
            relativeVolume = 1;
        }

        if (relativePan !== this.#relativePan || relativeVolume !== this.#relativeVolume){
            
            this.#relativePan = relativePan;
            this.#relativeVolume = relativeVolume;
            this.#audioChannels.forEach((ac)=>{
                if(ac!=null && ac instanceof VC.AudioChannel){
                    //log(relativePan);
                    ac.relativePan = relativePan;
                    ac.relativeVolume = relativeVolume;
                }
            });
        }
    }
    */

    #lastBox = null;
    move(deltaT) {
        if(this.#lastBox!=null){
            this.velocity = VC.Trig.distance(this.box.x, this.box.y, this.#lastBox.x, this.#lastBox.y);
            this.#lastBox.x = this.box.x;
            this.#lastBox.y = this.box.y;
        }else {
            this.velocity = 0;
            this.#lastBox = this.box.clone();
        }
    }

    render(deltaT, screen){
        if(!this.clearRegistered){
            screen.onClear(()=>{this.clear(); this.clearRegistered = false;})
            this.clearRegistered = true;
        }
    }

    clear(){
        this.box.remove();
    }

    remove(){
        //log("removing", this.code, this.id)
        this.removeAllSounds();
        this.#removed = true;
        this.box.remove();
        this.room = null;
    }

    removeAllSounds(){
        if(game && game.level && (this.room || this.backupRoom)){
                
            let s = new Sound(
                !this.room ? this.backupRoom : this.room,//TNT fix
                this.id,
                -1, //remove all
                -1,
                -1,
                false
            )
            game.level.soundScape.remove(
                s
            )

        }
    }
    
    playSound(channel, sound, loop){
        if(!this.#removed && game.level){
            let s = new Sound(
                !this.room ? this.backupRoom : this.room,//TNT fix
                this.id,
                channel,
                sound.id,
                1,
                loop ? true : false
            )
            s.tag = this.code;
            game.level.soundScape.add(
                s
            )
        }
    }
    
    stopSound(channel, sound){
        if(game.level){
            if(this.room || this.backupRoom){
                
                game.level.soundScape.add(
                    new Sound(
                        !this.room ? this.backupRoom : this.room,//TNT fix
                        this.id,
                        channel,
                        sound.id,
                        0
                    )
                )

            }
        }
    }
}

class HexagonalTileFloor extends Floor {
    type = "h";
    #sideLength = 0;
    #width = 0;
    #height = 0;
    #elements = [];
    constructor(sideLength){
        super();
        this.#sideLength = sideLength;
        this.#width = Math.sqrt(3) * sideLength; 
        this.#height = 2 * sideLength;
    }

    static fromData(data){
        var floor = new HexagonalTileFloor(data.l);
        floor._seed = data.s;
        return floor;
    }

    getData(){
        return {
            t: this.type, 
            l: this.#sideLength,
            s: this._seed
        }
    }

    getTile(x, y){
        return new VC.Polygon(
            new VC.Point(x + this.#width / 2, y),
            new VC.Point(x + this.#width, y + this.#height / 4),
            new VC.Point(x + this.#width, y + 3 * this.#height / 4),
            new VC.Point(x + this.#width / 2, y + this.#height),
            new VC.Point(x, y + 3 * this.#height / 4),
            new VC.Point(x, y + this.#height / 4)
        )
    }

    render(screen, roomBounds, floorColor){
        super.render(roomBounds);
        
        let t = this._seed;
        let row = 0;
        for(let y=this._minY-this.#height/2;y<this._maxY;y+=3 * this.#height / 4){
            let offset = 0
            if (row % 2 !== 0) {
                offset = this.#width / -2; 
            }
            for(let x=offset; x<this._maxX;x+=this.#width){

                let tile = this.getTile(x,y)

                if(roomBounds.collidesWith(tile)){
                    this.#elements.push(screen.drawPoly(tile.points, VC.Color.calculateAlpha(floorColor,Floor._tiles[t],.25),VC.Color.calculateAlpha(floorColor,"#000",.25),constants.groutThickness));
                }
                
                t = (t+1) % Floor._tiles.length;

            }
            row++;
        }

        return this;
    }

    remove(){
        super.remove();
        this.#elements.forEach((e)=>{e.remove()});
        this.#elements = [];
    }
}

const UP_ARROW = 38;
const RIGHT_ARROW = 39;
const DOWN_ARROW = 40;
const LEFT_ARROW = 37;
class InputController extends Controller {
    gamepads = [];
    r = 0;
    x = 0;
    dist = 0;
    dpadcover = null;
    touchsensor = null;
    dpadedge = null;
    mask = null;
    controller = null;
    controllerRadius = 210;
    controllerCrossThickness = 80;
    lineThickness = 2;

    constructor(){
        super();
        //screen = new VC.Screen("controller", 0, 0, Renderer.dimensions.width, Renderer.dimensions.height);
        let controller = this;
        window.onkeyup = function(e){
            switch (e.key){
                case "w":
                case "W":
                case "ArrowUp":
                    controller.up = 0;
                    break;    
                case "s":
                case "S":
                case "ArrowDown":
                    controller.down = 0;
                    break;
                case "a":
                case "A":
                case "ArrowLeft":
                    controller.left = 0;
                    break;
                case "d":
                case "D":
                case "ArrowRight":
                    controller.right = 0;
                    break;
                case " ":
                case 'Enter':
                    controller.attack = 0;
                    break;
                case 'J':
                    if(DEBUG){
                        game.level.currentRoom = game.level.findNeighbor(game.level.currentRoom,Direction.WEST);
                    }
                    break;
                case 'I':
                    if(DEBUG){
                        game.level.currentRoom = game.level.findNeighbor(game.level.currentRoom,Direction.NORTH);
                    }
                    break;
                case 'L':
                    if(DEBUG){
                        game.level.currentRoom = game.level.findNeighbor(game.level.currentRoom,Direction.EAST);
                    }
                    break;
                case 'K':
                    if(DEBUG){
                        game.level.currentRoom = game.level.findNeighbor(game.level.currentRoom,Direction.SOUTH);
                    }
                    break;
                case 'P':
                    if(DEBUG){
                        game.level.currentRoom = game.player.room;
                    }
                    break;
                default:
                    if(e.keyCode){
                        switch (e.keyCode){
                            case UP_ARROW:
                                controller.up = 0;
                                break;
                            case RIGHT_ARROW:
                                controller.right = 0;
                                break;
                            case DOWN_ARROW:
                                controller.down = 0;
                                break;
                            case LEFT_ARROW:
                                controller.left = 0;
                                break;
                            default:
                                return true;
                        }
                    }
            }
            e.handled= true;
            e.preventDefault();
            return false;
        };
        
        window.onkeydown = function(e){
            switch (e.key){
                case "w":
                case "W":
                case "ArrowUp":
                    controller.up = 1;
                    break;
                case "s":
                case "S":
                case "ArrowDown":
                    controller.down = 1;
                    break;
                case "a":
                case "A":
                case "ArrowLeft":
                    controller.left = 1;
                    break;
                case "d":
                case "D":
                case "ArrowRight":
                    controller.right = 1;
                    break;
                case " ":
                case 'Enter':
                    controller.attack = 1;
                    break;
                default:
                    if(e.keyCode){
                        switch (e.keyCode){
                            case UP_ARROW:
                                controller.up = 1;
                                break;
                            case RIGHT_ARROW:
                                controller.right = 1;
                                break;
                            case DOWN_ARROW:
                                controller.down = 1;
                                break;
                            case LEFT_ARROW:
                                controller.left = 1;
                                break;
                            default:
                                return true;
                        }
                    }
            }
            
            e.handled= true;
            e.preventDefault();
            return false;
        };
    }

    touchStartOrMove(e){
        e.preventDefault(e);
        //setVC.OrientationPortrait();
        
        let button = this.elements[this.elements.length-1];
        let dpad = this.dpadcover;
        let controller = this.touchsensor;
        
        let r = e.target.getBoundingClientRect();
     
        //r.y = r.y - Renderer.dimensions.infoHeight - Renderer.dimensions.width
        let touches = Array.from(e.touches);
        let dpadTouched = false;
        let buttonTouched = false;
        touches.forEach((t)=>{   
            
            //log(r,t,screen);
            //log(t);


            let x = (((t.clientX - r.x)/r.width))//*this.controllerRadius*2) - this.controllerRadius;
            let y = (((t.clientY - r.y)/r.height))//*this.controllerRadius*2) - this.controllerRadius;// * Renderer.dimensions.height;
            x = x * controller.attr("width");
            y = y * controller.attr("height") + (Renderer.dimensions.width + Renderer.dimensions.infoHeight);

            let d = dpad.getBBox();
            
            if(x>d.x && x<d.x + d.width && y>d.y && y<d.y+d.width){
                dpadTouched = true;
                //screen.drawRect(x,y, 10, 10, "#FF0", "#000",0)

                x = ((x - d.x)-d.width/2)/(d.width/2);
                y = ((y - d.y)-d.height/2)/(d.height/2)

                this.dist = VC.Math.constrain(0,VC.Trig.distance(x,y,0,0),1);

                this.r = VC.Trig.radiansToDegrees(Math.atan(y/x));
                this.x = x;
                d = Math.abs(VC.Trig.radiansToDegrees(Math.atan(y/x)));
                this.up = y < 0 && d > 23 ? 1 : 0;
                this.right = x > 0 && d < 68 ? 1 : 0;
                this.down = y > 0 && d > 22 ? 1 : 0;
                this.left = x < 0 && d < 68 ? 1 : 0;
            }
            
            let b = button.getBBox();
            if(x>b.x && x<b.x + b.width && y>b.y && y<b.y+b.width){
                dpadTouched = true;
                buttonTouched = true;
                this.attack = 1;
            }

        })
        if(!dpadTouched){
            this.up = 0;
            this.right = 0;
                this.down =  0;
                this.left = 0;
        }
        if(!buttonTouched){
            this.attack = 0;
        }
    }

    render(screen){
        let centerY = Math.round((Renderer.dimensions.height - Renderer.dimensions.width - Renderer.dimensions.infoHeight)/2 + Renderer.dimensions.width + Renderer.dimensions.infoHeight);
        let dPadLeft = Math.round(Renderer.dimensions.width/4);  
        if (this.elements.length ===0){
            
            //mask lower screen
            this.mask = screen.drawRect(-5, Renderer.dimensions.width + Renderer.dimensions.infoHeight, Renderer.dimensions.width+10, Renderer.dimensions.height, "#000", "#000", 0);

            let color="#242424";
            this.controller = screen.rect(0, Renderer.dimensions.width + Renderer.dimensions.infoHeight + 25, Renderer.dimensions.width, Renderer.dimensions.height - Renderer.dimensions.width - Renderer.dimensions.infoHeight - 50).attr({"fill":"90-#111-#242424:15-#242424:85-#444:100", "r": 100, "stroke-width":5, "stroke": "#242424"});
            color = "#2f2f2f";

            this.elements.push(screen.drawEllipse(dPadLeft, centerY, this.controllerRadius, this.controllerRadius,0,0,color,"#000",1));
            //color = "#444444";    
            this.elements.push(screen.drawLine(dPadLeft - this.controllerCrossThickness/2, centerY - (this.controllerRadius-8), dPadLeft - this.controllerCrossThickness/2, centerY + (this.controllerRadius-8),"#000",this.lineThickness))
            this.elements.push(screen.drawLine(dPadLeft + this.controllerCrossThickness/2, centerY - (this.controllerRadius-8), dPadLeft + this.controllerCrossThickness/2, centerY + (this.controllerRadius-8),"#000",this.lineThickness))
            
            this.elements.push(screen.drawLine(dPadLeft - (this.controllerRadius-8), centerY - (this.controllerCrossThickness/2), dPadLeft + (this.controllerRadius-8), centerY - (this.controllerCrossThickness/2),"#000",this.lineThickness))
            this.elements.push(screen.drawLine(dPadLeft - (this.controllerRadius-8), centerY + (this.controllerCrossThickness/2), dPadLeft + (this.controllerRadius-8), centerY + (this.controllerCrossThickness/2),"#000",this.lineThickness))
            
            this.elements.push(screen.drawRect(dPadLeft - this.controllerCrossThickness/2, centerY - this.controllerCrossThickness/2-this.lineThickness/2, this.controllerCrossThickness, this.controllerCrossThickness + this.lineThickness,color, color,4))
            this.elements.push(screen.drawLine(dPadLeft - this.controllerCrossThickness/2, centerY - this.controllerCrossThickness/2, dPadLeft + this.controllerCrossThickness/2, centerY + this.controllerCrossThickness/2,"#000",this.lineThickness))
            this.elements.push(screen.drawLine(dPadLeft + this.controllerCrossThickness/2, centerY - this.controllerCrossThickness/2, dPadLeft - this.controllerCrossThickness/2, centerY + this.controllerCrossThickness/2,"#000",this.lineThickness))
            let arrowMargin = 4 * this.lineThickness;
            let arrowHeight = 40;
            color = "#202020";
            this.elements.push(screen.drawTriangle(
                dPadLeft, centerY - this.controllerRadius + arrowMargin,
                dPadLeft + this.controllerCrossThickness/2 - arrowMargin, centerY - this.controllerRadius + arrowHeight, 
                dPadLeft - this.controllerCrossThickness/2 + arrowMargin, centerY - this.controllerRadius + arrowHeight,  
                0,0, color, "#000",0//this.lineThickness
            ));
            this.elements.push(screen.drawTriangle(
                dPadLeft + this.controllerRadius - arrowMargin, centerY,
                dPadLeft + this.controllerRadius - arrowHeight, centerY + this.controllerCrossThickness/2 - arrowMargin, 
                dPadLeft + this.controllerRadius - arrowHeight, centerY - this.controllerCrossThickness/2 + arrowMargin,  
                0,0, color, "#000",0
            ));
            this.elements.push(screen.drawTriangle(
                dPadLeft, centerY + this.controllerRadius - arrowMargin,
                dPadLeft + this.controllerCrossThickness/2 - arrowMargin, centerY + this.controllerRadius - arrowHeight, 
                dPadLeft - this.controllerCrossThickness/2 + arrowMargin, centerY + this.controllerRadius - arrowHeight,  
                0,0, color, "#000",0
            ));
            this.elements.push(screen.drawTriangle(
                dPadLeft - this.controllerRadius + arrowMargin, centerY,
                dPadLeft - this.controllerRadius + arrowHeight, centerY + this.controllerCrossThickness/2 - arrowMargin, 
                dPadLeft - this.controllerRadius + arrowHeight, centerY - this.controllerCrossThickness/2 + arrowMargin,  
                0,0, color, "#000",0
            ));
            
            
            let txt1 = screen.text(Math.round(Renderer.dimensions.width*.75), centerY - 180, "TAP TO WHIP").attr({ "font-size": "32px", "font-family": "monospace", "fill": "#CCC", "text-anchor": "middle", "font-weight": "bold"});  
            this.elements.push(txt1);
            
            let txt2 = screen.text(Math.round(Renderer.dimensions.width*.75), centerY + 180, "HOLD FOR TNT").attr({ "font-size": "32px", "font-family": "monospace", "fill": "#CCC", "text-anchor": "middle", "font-weight": "bold"});  
            this.elements.push(txt2);

            let el = screen.drawEllipse(Math.round(Renderer.dimensions.width*.75), centerY, this.controllerRadius/2, this.controllerRadius/2,0,0,"#800", "#000",8);
            this.elements.push(el);


            let fill = "90-rgba(180,180,180,0)-rgba(0,0,0,.2):50"
            this.dpadcover = screen.drawEllipse(dPadLeft, centerY, this.controllerRadius, this.controllerRadius,0,0,fill,null,0)

            this.touchsensor = screen.drawRect(0, Renderer.dimensions.width + Renderer.dimensions.infoHeight, Renderer.dimensions.width, Renderer.dimensions.height-(Renderer.dimensions.width + Renderer.dimensions.infoHeight),"#000","#000",0).attr({"opacity":.1})
            this.touchsensor.touchstart((e)=>{this.touchStartOrMove(e)});
            this.touchsensor.touchmove((e)=>{this.touchStartOrMove(e)});
            this.touchsensor.touchend((e)=>{this.touchStartOrMove(e)});
            

        }

        let butt = this.elements[this.elements.length-1];
        butt.attr({
            fill:this.attack ? "r#600-#800:90-#600:10" : "r#800-#a00:90-#800:10",
            rx:(this.controllerRadius/2) - (this.attack ? 2 : 0),
            ry:(this.controllerRadius/2) - (this.attack ? 2 : 0),
            "stroke-width": (this.attack ? 10 : 8)
        });

        butt.attr({})

        //let el = this.elements[this.elements.length-1];
        let e2 = this.elements[0];
        
        //read controller
        let x = this.left * -1 + this.right;
        let y = this.up * -1  + this.down;

        let degrees = 0;
        //read state



        degrees = 
            x === -1 && y === 1 ? 225 :
            x === 1 && y === -1 ? 45 :
            x === -1 && y === -1 ? 315 :
            x === 1 && y === 1 ? 135 :
            x === -1 ? 270 :
            x === 1 ? 90 :     
            y === -1 ? 0 :
            y === 1 ? 180 : 
            0 ;
        let d = -90
        if(this.x>0 || this.right){//} || (this.up && !this.left && !this.right) ){
            d=90;
        }

        let o = ((Math.round((this.dist/2)*100)/100)+"").replace("0.",".");
        let fill = "90-rgba(100,100,100," + o + ")-rgba(0,0,0,1):50"
        let e = 1
        if((x === 0 && y === 0)||o<=.01){
            fill="#000";
            e = 0
        }
        if(this.dpadedge){
            this.dpadedge.remove()
            this.dpadedge = null;
        }
        this.dpadedge = screen.drawEllipse(dPadLeft, centerY, this.controllerRadius+8, this.controllerRadius+8,0,0, fill,"#000",e);
        
        this.elements[0].toBack();
        this.dpadedge.toBack();
        this.controller.toBack();
        this.mask.toBack();
        
        if(x === 0 && y === 0){
            if(this.dpadcover) this.dpadcover.hide();
            //if(this.dpadedge) this.dpadedge.hide();
            return;
        }
        if(this.dpadcover){
            this.dpadcover.remove()
            this.dpadcover = null;
        }
        
        o = ((Math.round((this.dist/4)*100)/100)+"").replace("0.",".");
        fill = "90-rgba(180,180,180,0)-rgba(0,0,0," + o + "):50"
  
        this.dpadcover = screen.drawEllipse(dPadLeft, centerY, this.controllerRadius, this.controllerRadius,0,0,fill,null,0)
        this.touchsensor.toFront();
        this.dpadcover.attr({"opacity":.2})
        //this.elements.push(el2);


        //el.show();
        this.dpadcover.transform("r" + (360+(this.r+d))%360 + "," + dPadLeft + "," + centerY);
        //log(o)
        //el.attr({})
        //el.attr({"opacity":this.dist/5})                
        
        //e2.show();
        this.dpadedge.transform("r" + (360+(this.r+d))%360 + "," + dPadLeft + "," + centerY);
        //this.dpadEdge.attr({"stroke-opacity":this.dist})
        //log(el.attr());
        
    }

    read(forObject){
        //read joysticks
        this.gamepads = navigator.getGamepads();
        if(this.gamepads && this.gamepads.length>0){
            let gamepad = this.gamepads[0];
            if (gamepad != null){
                this.attack = (gamepad.buttons && gamepad.buttons.length>0 && gamepad.buttons[0]!=null && gamepad.buttons[0].pressed) ? 1 : 0;
                if(gamepad.axes && gamepad.axes.length>1){
                    this.right = Math.round(gamepad.axes[0])>0;
                    this.left = Math.round(gamepad.axes[0])<0;
                    
                    this.down = Math.round(gamepad.axes[1])>0;
                    this.up = Math.round(gamepad.axes[1])<0;
                        
                }
            }
        }
        return super.read(forObject);
    }
}

