class NoiseFloor extends Floor {
    type = "n";
    
    #elements = [];

    static defineNoise(screen){
        let noise = document.getElementById("noise");
        if(noise == null){
            let noiseSize = 970;
            noise = document.createElementNS(screen.svgNS, "pattern");
            noise.setAttribute("id","noise");
            noise.setAttribute("width", noiseSize/2);
            noise.setAttribute("height", noiseSize/2);
            noise.setAttribute("patternUnits", "userSpaceOnUse");
            
            let image = document.createElementNS(screen.svgNS, "image");
            image.setAttribute("href", Images.NOISE);
            image.setAttribute("width", noiseSize/2);
            image.setAttribute("height", noiseSize/2);
            
            noise.appendChild(image);
            screen.defs.appendChild(noise);
        }
    }

    static fromData(data){
        return new NoiseFloor();

    }

    getData(){
        return {
            t: this.type
        }
    }

    constructor(){
        super();
    }

    render(screen, roomBounds, floorColor){
        super.render(roomBounds);
        NoiseFloor.defineNoise(screen);
        log(this);
        let noiselayer = screen.drawRect(this._minX,this._minY, this._maxX, this._maxY, null);
        noiselayer.node.setAttribute("fill", "url(#noise)");
        let overlay = screen.drawRect(this._minX,this._minY, this._maxX, this._maxY,floorColor);
        overlay.attr({opacity:.95})
        this.#elements = [noiselayer, overlay];
        
        return this;
    }

    remove(){
        super.remove();
        this.#elements.forEach((e)=>{e.remove()});
        this.#elements = [];
    }
}

class PlayerInput extends Message{
    constructor(){
        super();
        this.messageType = MessageType.PLAYER_INPUT;
        this.data.x = 0;
        this.data.y = 0;
        this.data.z = 0;
    }
    get x() {
        return this.data.x;
    }
    set x(value) {
        this.data.x = value;
    }
    get y(){
        return this.data.y;
    }
    set y(value){
        this.data.y = value;
    }
    get a(){
        return this.data.a;
    }
    set a(value){
        this.data.a = value;
    }
    static map(obj){
        var pi = new PlayerInput();
        pi.x = obj.x;
        pi.y = obj.y;
        pi.a = obj.a;
        return pi; 
    }
    static parse(obj){
        if(obj.messageType!=MessageType.PLAYER_INPUT){
            throw ('cannot map unexpected object')
        }
        var pi = new PlayerInput()
        pi.sender = obj.sender;
        pi.data = obj.data;
        return pi; 
    }
}

class ReadyPlayer extends Message{
    constructor(){
        super();
        this.messageType = MessageType.READY_PLAYER;
        this.data.n = "";
        this.data.t = 0;
        this.data.l = [];
        //todo: add inventory 
    }
    get syncTime(){
        return this.data.t;
    }
    set syncTime(value){
        this.data.t = value
    }
    get playerName(){
        return this.data.n;
    }
    set playerName(value){
        this.data.n = value;
    }
    get playTime(){
        return this.data.t;
    }
    set playTime(value){
        if(isNaN(value)){
            return;
        }
        this.data.t = value;
    }

    get levelState(){
        return this.data.l;
    }
    set levelState(value){
        return this.data.l= value;
    }
    static parse(obj){
        if(obj.messageType!=MessageType.READY_PLAYER){
            throw ('cannot map unexpected object')
        }
        var pi = new ReadyPlayer()
        pi.sender = obj.sender;
        pi.data = obj.data;
        return pi; 
    }
}

class RectangularTileFloor extends Floor {
    type = "r";
    #tileWidth = 0;
    #tileHeight = 0;
    #elements = [];

    constructor(tileWidth, tileHeight){
        super();
        this.#tileWidth = tileWidth;
        this.#tileHeight = tileHeight;
    }

    static fromData(data){
        var floor = new RectangularTileFloor(data.w, data.h);
        floor._seed = data.s;
        return floor;
    }

    getData(){
        return {
            t: this.type, 
            w: this.#tileWidth,
            h: this.#tileHeight,
            s: this._seed,
        }
    }

    render(screen, roomBounds, floorColor){
        super.render(roomBounds);

        let t = this._seed;
        for(let y=this._minY;y<this._maxY;y+=this.#tileHeight){
            for(let x=this._minX; x<this._maxX;x+=this.#tileWidth){
                let w = this.#tileWidth;
                let h = this.#tileHeight;
                if(x+w>this._maxX){
                    w = this._maxX - x;
                }
                if(y+h>this._maxY){
                    h = this._maxY - y;
                }
                
                let p = new VC.Polygon(
                    new VC.Point(x,y),
                    new VC.Point(x+w,y),
                    new VC.Point(x+w,y+h),
                    new VC.Point(x,y+h)
                );


                if(roomBounds.collidesWith(p)){
                    this.#elements.push(screen.drawRect(x, y, w, h, VC.Color.calculateAlpha(floorColor,Floor._tiles[t],.25),VC.Color.calculateAlpha(floorColor,"#000",.25),constants.groutThickness));
                }
                
                t = (t+1) % Floor._tiles.length;
            }
        }
        return this;
    }

    remove(){
        super.remove();
        this.#elements.forEach((e)=>{e.remove()});
        this.#elements = [];
    }
}
