class ServerSoundScape {
    #sounds = new Map();
    constructor(){
        //clean up regularly
        setInterval(()=>{this.prune();}, 500);
    }
    add(sound){
        let roomKey = sound.room.getData();
        if(!this.#sounds.has(roomKey)){
            this.#sounds.set(roomKey, []);
        }
        this.remove(sound);//remove any other sound command on this object & channel.
        this.#sounds.get(roomKey).push(sound);
    }
    remove(sound){
        let roomKey = sound.room.getData();
        if(!this.#sounds.has(roomKey)){
            return;
        }
        let removeAt = -1;
        this.#sounds.get(roomKey).forEach((s, i) => {
            if(
                s.originatorObjectId==sound.originatorObjectId && 
                (s.channelId == sound.channelId || sound.channelId == -1)//remove all
            ){
                removeAt = i;
            }
        });
        if(removeAt != -1){
          this.#sounds.get(roomKey).splice(removeAt, 1);  
        }
    }
    prune(){
        let currentTime = Date.now() - (server && server.syncTime ? server.syncTime : client.syncTime);
        let level = game ? game.level : null;
        this.#sounds.forEach((soundArray)=>{
            remove(soundArray, (s)=>{
                if(!s.isMusic){
                    let go = s.originatorObjectId==-1 ? null : level ? level.findObjectById(s.originatorObjectId) : null;
                    return (
                        (
                            go && go.state != State.DEAD
                        ) || (
                            s.soundCommand == 1 && 
                            s.loop == false &&
                            s.commandTime + SoundEffects.INDEX[s.soundId].length < currentTime
                        ) || (
                            s.soundCommand == 0 &&
                            s.commandTime + SoundEffects.INDEX[s.soundId].length + 500 < currentTime    
                        )
                    )
                }
                return false;
            });
        });
    }
    filter(x,y){
        let result = [];
        this.#sounds.forEach((soundBank,roomKey)=>{
            if(
                (roomKey.x==x && roomKey.y>=y-1 && roomKey.y<=y+1) ||
                (roomKey.y==y && roomKey.x>=x-1 && roomKey.x<=x+1)
            ){
                result.push(...soundBank)
            }
        });
        return result;
    }
}

