class Renderer extends VC.Game {
    static dimensions = {
        width: 910, 
        height: 1618,
        infoHeight: 88,
    };
    
    #infoScreen = null;
    #mainScreen = null;
    #controllerScreen = null;
    #inputController = null;
    #currentScene = null;
    #slot = null;
    #musicChannel = null;
    #audioChannels = null;
    soundScape = new ClientSoundScape()

    constructor(){
        super()
        this.bootstrapScreens()
        this.#inputController = new InputController(this.#controllerScreen);
        this.play();

        this.#musicChannel = new VC.AudioChannel();
        this.#audioChannels = [
            new VC.AudioChannel(),
            new VC.AudioChannel(),
            new VC.AudioChannel(),
            new VC.AudioChannel(),
            new VC.AudioChannel()
        ];
        /*
        if(this.DEBUG || System.isLocal){
            this.currentScene = new TitleScreen(this.screen, this.infoScreen);
        } else if(System.newClient){
            this.currentScene = new BetaScreen();
        }else {
            this.currentScene = new TitleScreen(this.screen, this.infoScreen);
        }
        */

       //this.currentScene.preDisplay(); //why is this needed?
    }
    
    #nextAudioChannel = 0;
    get audioChannel(){
        let n=this.#nextAudioChannel;
        this.#nextAudioChannel = this.#nextAudioChannel + 1;
        this.#nextAudioChannel = this.#nextAudioChannel % this.#audioChannels.length;
        return this.#audioChannels[n];
    }

    get mainScreen(){
        return this.#mainScreen;
    }
    
    get infoScreen(){
        return this.#infoScreen;
    }
    
    get controllerScreen(){
        return this.#controllerScreen;
    }
    get inputController(){
        return this.#inputController;
    }
    get slot(){
        return this.#slot;
    }
    set slot(value){
        this.#slot = value;
    }

    createScreen(parent, id, x, y, width, height){
        let div = document.createElement("div");
        div.id = id;
        div.className = "screen";
        div.style.position = "absolute";
        div.style.top = "0px";
        div.style.left = "0px";
        parent.appendChild(div);
        return new VC.Screen(id, x, y, width, height);
    }

    bootstrapScreens(){
        let screens = document.createElement("div");
        screens.id = "screens";
        screens.className = "screen";
        document.body.appendChild(screens);

        this.#infoScreen = this.createScreen(screens, "info", 0, 0, Renderer.dimensions.width, Renderer.dimensions.height);
        this.#mainScreen = this.createScreen(screens, "main", 0, 0, Renderer.dimensions.width, Renderer.dimensions.width);
        this.#controllerScreen = this.createScreen(screens,"controller", 0, 0, Renderer.dimensions.width, Renderer.dimensions.height);
    }

    changeOrientation(){
        if(VC.System.orientation === VC.Orientation.PORTRAIT){
            document.getElementById("controller").style.display = "block";    
            renderer.mainScreen.setViewBox(0, -Renderer.dimensions.infoHeight, Renderer.dimensions.width, Renderer.dimensions.height, true);    
            renderer.infoScreen.setViewBox(0, 0, Renderer.dimensions.width, Renderer.dimensions.height, true); 
            return;
        }
        document.getElementById("controller").style.display = "none";
        renderer.mainScreen.setViewBox(0, -Renderer.dimensions.infoHeight, Renderer.dimensions.width, Renderer.dimensions.width + Renderer.dimensions.infoHeight, true); 
        renderer.infoScreen.setViewBox(0, 0, Renderer.dimensions.width, Renderer.dimensions.width + Renderer.dimensions.infoHeight, true);    
    }
    get currentScene(){
        return this.#currentScene;
    }
    #transitioningTo = null;
    get transitioningTo(){
        if(this.#transitioningTo){
            return this.#transitioningTo.sceneName;
        }
        return "";
    }
    set currentScene(value){
        if(value && (!this.#currentScene || this.#currentScene.sceneName!=value.sceneName) && (!this.#transitioningTo || this.#transitioningTo.sceneName != value.sceneName)){
            
            this.#transitioningTo = value;
            log("setting scene")
            this.halt();
            let fadeColor = SCREENBLACK; 
            if ((this.currentScene instanceof TitleScreen)){// || (this.currentScene instanceof GameOverScreen)){
                fadeColor = "#FFF"
            }
            this.mainScreen.fadeTo(fadeColor, ()=>{
                if(this.#currentScene){
                    this.currentScene.postDisplay();
                    this.mainScreen.clear();
                }
                if(this.#transitioningTo){
                    this.#currentScene = this.#transitioningTo;
                    log(this.#transitioningTo)
                    this.#currentScene.preDisplay();
                    //render one frame
                    this.onRender(0);
                    this.mainScreen.fadeInFrom(fadeColor,()=>{;
                        this.play();
                        this.#transitioningTo = null;
                    })

                }
            });
        }
    }

    onRender(deltaT){
        if(this.currentScene){
            this.currentScene.render(deltaT, this.mainScreen)
        }
        
        if(this.#currentScene instanceof Level && client){
            //console.log("objects",this.currentScene.rooms[0].objects);
            if(this.statusOverlay==null){
                this.statusOverlay = new StatusOverlay();
            }
            let currentPlayer = this.#currentScene.players.get(client.id);
            let spectating = this.#currentScene.players.get(currentPlayer.spectating);
            if(spectating && spectating.gameObject){
                this.statusOverlay.playerGameObject = spectating.gameObject;
                this.statusOverlay.spectating = (spectating != currentPlayer);
                this.statusOverlay.render(deltaT, this.infoScreen);
            }
        }else {
            if(this.statusOverlay!=null){
                this.statusOverlay.postDisplay();
                this.statusOverlay == null;
                this.infoScreen.clear();
            }
        }
        
        if (this.inputController){
            //Render our controller
            this.inputController.render(this.controllerScreen);//TODO: find a better way to reference this. 
        }
        
    }

    #pauseElement = null;
    onPause(){
        /*
        if(this.#pauseElement == null){
            this.#pauseElement = this.screen.text(dimensions.width/2, dimensions.infoHeight * 5,"- PAUSED -").attr({ "font-size": "64px", "font-family": "monospace", "fill": "#FFF", "text-anchor": "center"});
            Howler.mute(true);
        }
        this.inputController.render();
        let input = this.inputController.read();
        if(input.a){
            log("unpausing");
            this.#pauseElement.remove();
            this.#pauseElement = null;
            //no, really: unmute
            Howler.mute(false);
            Howler.mute(false);
            Howler.mute(false);
            this.play();
        }
            */
    }
    
    #lastMusic = null;
    get lastMusic(){
        return this.#lastMusic
    }
    playMusic(sound){
        if(sound.id !=this.#lastMusic ){
            this.#musicChannel.fadeOut(()=>{this.#musicChannel.play(sound.data, (this.slot ? this.slot.musicVolume : 0.15) *  (sound.id == Music.INFERNUS.id || sound.id == Music.CHARGE.id ? 2 : 1), true)});
            this.#lastMusic = sound.id;
        }
    }
    stopMusic(){
        this.#musicChannel.fadeOut(()=>{});
    }

}

class TNT extends GameObject{
    code="tn";
    sprite = null;
    #shadow = null;
    #forceRender = false;
    constructor(room){
        super(room);
        this.health = 1;
        this.box.width = 24;
        this.box.height = 24;
        this.layer = Layer.DEFAULT;
        this.state = State.THROWING;
        this.stop = false;
        this.z = 100;
        this.waterOffset = 25;
    }

    init(){
        if(!this.initialized){
            this._fuseStart = Date.now();
            this.timeoutHandle = window.setTimeout(()=>{
                this.attack()
            },2000)
            this.playSound(0, SoundEffects.FUSE, false)
            this.initialized = true
        }
    }

    attack(){
        if(this.defused){
            return;
        }
        /*
        if(this.room == null){
            if(game && game.level && game.level.currentRoom){
                this.room = game.level.currentRoom;
            }else{
                return;
            }
        }
        */
        if(this.state !== State.DEAD){  
            let ex = null;     
            ex = new Explosion(this.room ? this.room : this.backupRoom, this.box.center().x, this.box.center().y)
            
            if (this.room){       
                this.room.objects.filter(o=>o instanceof WaterPool).forEach(wp=>{
                    if(this.box.collidesWith(wp.box)){//TODO: update for polygonal water pools
                        ex.suppressScorch = true;
                    }
                });
            }
        }
    
        this.stopSound(0, SoundEffects.FUSE);

        this.state = State.DEAD;
    
    }

    hurt(){
        this.health = 0; 
        this.attack();
    }


    move(deltaT){
        this.init();
        if(this.state===State.DEAD || this.state == State.THROWING){
            return;
        }
        let speed = 0 
        if(this.state !== State.IDLE){
            this.#forceRender = true;
            let releaseSpeed = 400;
            let msPassed = new Date() - this._stateStart;
            let factor = (1-(msPassed/2000));
            speed = releaseSpeed * factor
            //log(factor);    
        }

        let proposed = {
            room: this.room,
            x: this.box.x,
            y: this.box.y
        } 
        switch(this.direction){
            case Direction.NORTH:
                proposed.y = this.box.y - speed * deltaT/1000;
                break;
            case Direction.EAST:
                proposed.x = this.box.x + speed * deltaT/1000;
                break;
            case Direction.SOUTH: 
                proposed.y = this.box.y + speed * deltaT/1000;
                break;
            case Direction.WEST:
                proposed.x = this.box.x - speed * deltaT/1000;
                break;
        }

        let constrained = this.room.constrain(this,
            proposed.x,
            proposed.y
        )
        if ((Math.abs(constrained.x - proposed.x)>=1 || Math.abs(constrained.y - proposed.y)>=1) && proposed.room === this.room)
        {
            this.state = State.IDLE;
        }
        this.box.x = constrained.x;
        this.box.y = constrained.y;

        if(speed<=.5){
            this.plane = Plane.ETHEREAL;
        }


        this.z = 0;
        if(this.state!==State.IDLE || this.forceRender){
            let msPassed = new Date() - this._stateStart;
            let perc = 1-(msPassed/2000);
            let factor = Math.PI - ((Math.PI-1)*(perc));
            this.z = VC.Math.constrain(0, 50 * Math.sin(factor*1.5), 50);
        }
        super.move();
    }    

    render(deltaT, screen){
        super.render(deltaT, screen);

        if(this.z<=5 ){
            this.layer = Layer.SHADOW;
        }

        if(this.state === State.DEAD || this.state==State.THROWING){
            return;
        }
        
        if(!this.sprite){
            this.sprite = new VC.Sprite(screen, Images.TNT, 384, 24, 24, 24, this.box.center().x-12 , this.box.center().y-12 );
            this.sprite.setAnimation(0,0);
        }
           
        let x = this.box.center().x - 4;
        let y = this.box.center().y + 5;
        if(!this.#shadow){
            this.#shadow = screen.drawEllipse(x , y , 8, 2, 0, 0, "#111","#111",".5");
            this.#shadow.transform("r0,0,45");// + x +"," + y +  ",1") 
            this.#shadow.attr({"opacity": .5, "r":45});
            this.room.shadowGroup.addElement(this.#shadow);
        }
        this.#shadow.animate({"cx":x , "cy":y }, deltaT, 'linear');
        


        if(DEBUG){
            this.box.render(screen, "#800");
        }

        this.sprite.location.x = this.box.x ;
        this.sprite.location.y = this.box.y  - this.z;

        this.sprite.setFrame(0,0,Math.round(VC.Math.percentToRange((Date.now()-this._fuseStart)/2000,0,15)))
        this.sprite.render(deltaT); 
    }

    defuse(){
        this.defused = true;
        window.clearTimeout(this.timeoutHandle);
        this.stopSound(0, SoundEffects.FUSE);
        var stick = new Pickup(this.room, Treasure.TNT, true);
        stick.box.center(this.box.center());
        stick.playSound(0,SoundEffects.LAVA_SIZZLE, 0)
        this.state = State.DEAD;
    }

    clear(){
        //super.clear(); SIC: avoiding cancellation of sound when crossing room boundaries. 
        this.box.remove();
        if(this.sprite){
            this.sprite.remove();
            this.sprite = null;
        }
        if(this.#shadow){
            this.#shadow.remove();
            this.#shadow = null;
        }
    }
    
    remove(){
        this.clear();
        super.remove();
    }
   
}
class WaterTemple extends Temple{
    static music = Music.EXPLORATION;
    #palette = new Palette(
        "#19351A",//clip color
        "#442A01",//floor color
        "#505347"//wall color
    );
    constructor(){
        super();
    }

    get name(){
        return "Seryndal"
    }
    
    get description(){
        return "The Ocean Temple"
    }

    
    get palette(){
        return this.#palette;
    }
    
    themeLevel(level){
        super.themeLevel(level);
        Temple.addTorches(level);
        
        level.rooms.forEach((room, index) => this.themeRoom(room, index, level));

        if (level.number % 5 === 0){
            level.message = this.name;
        }
    }
    
    themeRoom(room, index, level){
        log("themeing water")
        const waterPoolMinArea= (constants.brickWidth * constants.roomMaxWidthInBricks * constants.brickWidth * constants.roomMaxHeightInBricks) / 2;
        super.themeRoom(room, index);
        if(room.bounds.area()>=waterPoolMinArea && VC.Math.random(0,2)<2 && !room.exit){
            new WaterPool(room);
        }
        
        if (index !== 0 && !room.exit && !room.secret && level && level.number % 5 != 4){
            
            var enemyRange = level.number % 5 < 2 ? 2 : 3;
        
            let enemies = VC.Math.random(room.spawnDensity-1, room.spawnDensity + 1)
            for(let i=0; i<enemies; i++){   
                    room.spawn(new Crabman(room, new AutoController()));
            }
        }

    }
}

class Client extends VC.Client {
    #intervalHandle = null;
    ignore = false;
    otherPlayers=[];
    syncTime = Date.now();
    enableLogging = false;

    constructor(){
        super();
    }
    connected(){
        //TODO: if slot selected, send info.
        var msg = new ReadyPlayer();
        msg.sender = this.id;
        msg.playerName = renderer.slot.name;
        msg.playTime = renderer.slot.timeSpent;
        msg.levelState = renderer.slot.levelState;
        this.send(msg);
    }
    #lastRead = null;
    #sameRead = 0 
    pollController(){
        if(this.isConnected){
            
            let thisRead = renderer.inputController.read();
            if(Controller.areEqualReads(this.#lastRead, thisRead)){
                this.sameRead++;
            }else{
                this.sameRead = 0;
                this.#lastRead = thisRead;
            }
            if(this.sameRead<3){
                let msg = PlayerInput.map(thisRead)
                msg.sender = this.id;
                this.send(msg);
            }
        }else{
            window.clearInterval(this.#intervalHandle);
        }
    }
    received(data){
        //
        if(this.ignore){
            return;
        }
        let message = MessageDecoder.deserialize(data);
        if(message instanceof ReadyPlayer){
            this.syncTime = message.syncTime;
            if(message.sender == this.id){
                //server is ready, begin sending input. 
                this.intervalHandle = window.setInterval(()=>{this.pollController()}, 33);
            }else if(this.otherPlayers.indexOf(message.sender)==-1) {
                this.otherPlayers.push(message.sender);//useful?
            }
        }
        if(message.messageType == MessageType.SCENE_DATA){
            if(!renderer.currentScene || (renderer.currentScene.sceneName!=message.data.sceneName && renderer.transitioningTo != message.data.sceneName )){
                //console.log("setting New scene")
                //console.log("creating", message.data)
                let newScene = SceneManager.CreateScene(message.data.sceneName);
                newScene.setData(message.data);
                renderer.currentScene = newScene; 
            }else if(renderer.currentScene && renderer.currentScene.sceneName==message.data.sceneName){
                //console.log("updating scene");
                if (this.enableLogging){
                    console.log("updating", message.data);
                }
                renderer.currentScene.setData(message.data);
            }
            else{
                console.log("not ok");
            }
        }else{
            log("messagetype:", message.messageType)
        }

    }


}
