class LevelFactory {
 
    static Construct(levelNumber){
        Room.idCounter = 1;
        GameObject.idCounter = 0;
        if(levelNumber<0){
            return TestLevelFactory.Construct();
        }
        let hasBoss = (levelNumber % 5 === 4);
        //todo: call BossLevelFactory when Appropriate
        if(hasBoss){
            if((Math.floor(levelNumber / 5) + 1) ==2){
                return InfernusLevelFactory.Construct(levelNumber);
            } else {
                return BossLevelFactory.Construct(levelNumber);
            }
        }
        

        let level = new Level();
        level.number = levelNumber;
        level.statistics.levelNumber = levelNumber;

        //let defaultOffset = constants.doorWidth + constants.brickWidth + constants.doorFrameThickness * 3;
        
        let roomsPerRegion = 0;
        let maxRegion = 0;
        if(level.number <= 23){
            roomsPerRegion = ((level.number % 5 + 1) * 5) + 5;
            maxRegion = Math.floor(level.number/5);
        } else {
            roomsPerRegion = (((level.number - 24) + 1) * 5) + 25;
            maxRegion = Treasure.BLUEKEY;
        }

        level.palette = LevelFactory.getWorldPalette(level.world);

        //build map
        for(let region = 0; region <= maxRegion; region++){
            let regionRooms = [];
            //get entrance
            let entrance;
            level.doorCount = 0;
            if(level.rooms.length===0){
                entrance = level.getRoom(0,0);
         
            } else {
                let extents = level.extents();
                
                //pick a random direction
                let direction = Math.round(4 * Math.random()) % 4;
         

                let extent = extents[direction];
                switch(direction){
                    case Direction.NORTH:
                        entrance = level.getRoom(extent.x, extent.y - 1);
                        break;
                    case Direction.EAST:
                        entrance = level.getRoom(extent.x + 1, extent.y);
                        break;
                    case Direction.SOUTH:
                        entrance = level.getRoom(extent.x, extent.y + 1);
                        break;
                    case Direction.WEST:
                        entrance = level.getRoom(extent.x - 1, extent.y);
                        break;
                }
                //regionRooms.push(entrance);

                // Lock entrance if not starting position.

                let lockedDoor = new Door(level,extent,direction, 0)
                lockedDoor.lock = region;
                lockedDoor.opened = false;
                lockedDoor.color = regionColor(lockedDoor.lock + Treasure.SILVERKEY - 1);
                
                // Lock entrance if not starting position.
                entrance.opened = false;
                entrance.lock = region;
                entrance.region = region;

                //console.log("Lock 1")
                extent.doors.push(lockedDoor);
                entrance.doors.push(new Door(level,entrance,(direction + 2) % 4, 0));
                level.statistics.doorsSpawned++;
            }

            entrance.region = region;
            regionRooms.push(entrance); 
            
            while(regionRooms.length < roomsPerRegion){
                let seedRoom = randomEntry(regionRooms);
                if (seedRoom === regionRooms[0] && seedRoom.doors.length === 3)
                {
                    continue;
                }
                let seedDirection = Math.round(4 * Math.random()) % 4;
                if(seedRoom.findDoor(seedDirection)==null){
                    let neighbor = level.findNeighbor(seedRoom,seedDirection);
            
                    
                    if(neighbor == null){
                        switch(seedDirection){
                            case Direction.NORTH:
                                neighbor = level.getRoom(seedRoom.x, seedRoom.y - 1);
                                break;
                            case Direction.EAST:
                                neighbor = level.getRoom(seedRoom.x + 1, seedRoom.y);
                                break;
                            case Direction.SOUTH:
                                neighbor = level.getRoom(seedRoom.x, seedRoom.y + 1);
                                break;
                            case Direction.WEST:
                                neighbor = level.getRoom(seedRoom.x - 1, seedRoom.y);
                                break;
                            default:
                                console.warn({"unexpected seedDirection": seedDirection});
                                
                        }
                        regionRooms.push(neighbor);
                    }else{
                        if(neighbor.region!==region || neighbor === regionRooms[0]){
                            continue
                        }
                    }

                    neighbor.region = region;   
                    seedRoom.doors.push(new Door(level,seedRoom,seedDirection, 0));
                    neighbor.doors.push(new Door(level,neighbor,(seedDirection + 2) % 4, 0));
                }
            }
        }
        
        let exitRoom;
        let maxKey = Treasure.SILVERKEY;
        if(level.number <= 19){
            let extents = level.extents();
                
            //pick a random direction
            let direction = Math.round(4 * Math.random()) % 4;
     
            let extent = extents[direction];
            switch(direction){
                case Direction.NORTH:
                    exitRoom = level.getRoom(extent.x, extent.y - 1, null, null, null, true);
                    break;
                case Direction.EAST:
                    exitRoom = level.getRoom(extent.x + 1, extent.y, null, null, null, true);
                    break;
                case Direction.SOUTH:
                    exitRoom = level.getRoom(extent.x, extent.y + 1, null, null, null, true);
                    break;
                case Direction.WEST:
                    exitRoom = level.getRoom(extent.x - 1, extent.y, null, null, null, true);
                    break;
            }
            //regionRooms.push(entrance);

 
            //console.log("Lock 2")

            exitRoom.opened = false;
            maxKey = maxRegion + 1;
            exitRoom.lock = maxKey;
            exitRoom.region = maxKey;

           //Lock entrance if not starting position.
            let lockedDoor = new Door(level,extent,direction, 0)
            lockedDoor.lock = maxKey;
            lockedDoor.opened = false;
            lockedDoor.color = regionColor(maxKey + Treasure.SILVERKEY - 1);

            extent.doors.push(lockedDoor);
            exitRoom.doors.push(new Door(level,exitRoom,(direction + 2) % 4, 0));
            level.statistics.doorsSpawned++;
          
        } else {
            let extents = level.extents();   
            exitRoom = randomEntry(filter(extents,(r)=>{return r.doors.length===1 && r.region === maxRegion}))
            maxKey = maxRegion;
        }
        
        exitRoom.box.height = VC.Math.constrain((constants.roomMinHeightInBricks+2) *constants.brickWidth, exitRoom.box.height, constants.roomMaxHeightInBricks * constants.brickWidth)

        exitRoom.exit = 1;

        //trim doors
        level.rooms.forEach((r)=>{
            if(r.doors.length===4 && !(r.x===0 && r.y===0)){
                //pick a random direction
                let direction = VC.Math.random(0,3);
                let direction2 = (direction + 2) % 4
               
                let r2 = level.findNeighbor(r,direction);
               
                if (!LevelFactory.hasOrphans(level, [r.findDoor(direction), r2.findDoor(direction2)])){
                    if(r2.doors.length === 4 && !(r2.x===0 && r2.y===0)){
                        r.doors.splice(r.doors.indexOf(r.findDoor(direction)), 1);
                        r2.doors.splice(r2.doors.indexOf(r2.findDoor((direction + 2) % 4)), 1);
                    }
                }
            }
        });

        let secretCount = VC.Math.random(0,2)
        for(var s = 0; s<secretCount; s++){
                
            //Add Secret Room
            var eligible = [];
            level.rooms.forEach((r)=>{
                if(exitRoom == r) {
                    return;
                }
                if(r.secret){
                    return;
                }
                if(r.x==0 && r.y==0){
                    return;
                }
                if(
                    level.findNeighbor(r,0)==null || 
                    level.findNeighbor(r,1)==null || 
                    level.findNeighbor(r,2)==null || 
                    level.findNeighbor(r,3)==null
                ){
                    eligible.push(r);
                }
            });
            
            let secretRoomEntrance = randomEntry(eligible);
            //find an eligibleDirection
            let directions = []
            if(level.findNeighbor(secretRoomEntrance,0)==null){
                directions.push(0);
            }
            if(level.findNeighbor(secretRoomEntrance,1)==null){
                directions.push(1);
            }
            if(level.findNeighbor(secretRoomEntrance,2)==null){
                directions.push(2);
            }
            if(level.findNeighbor(secretRoomEntrance,3)==null){
                directions.push(3);
            }
            let secretRoomDirection = randomEntry(directions);
            
            let srx = 0;
            let sry = 0;
            switch(secretRoomDirection){
                case Direction.NORTH:
                    srx = secretRoomEntrance.x;
                    sry = secretRoomEntrance.y - 1;
                    break;
                case Direction.EAST:
                    srx = secretRoomEntrance.x + 1;
                    sry = secretRoomEntrance.y;
                    break;
                case Direction.SOUTH:
                    srx = secretRoomEntrance.x; 
                    sry = secretRoomEntrance.y + 1;
                    break;
                case Direction.WEST:
                    srx = secretRoomEntrance.x - 1;
                    sry = secretRoomEntrance.y;
                    break;
            }
            let sd = new SecretDoor(level, secretRoomEntrance, secretRoomDirection, 0);
            sd.stabilize();
            secretRoomEntrance.doors.push(sd);
            let sr = level.getRoom(srx,sry);
            sr.secret = true;
            sd = new SecretDoor(level, sr, (secretRoomDirection + 2) % 4, 0);
            sd.stabilize();
            sr.doors.push(sd);
        }
        

        //jitter rooms
        for(let i=0;i<level.rooms.length;i++){
            
            let room = level.rooms[i];
            room.jittered = true;
            if(i === 0){
            
                room.doors.forEach((d)=>{d.stabilize()});
               continue;
            }
            room.box.x = Math.round(Math.random() * ((Renderer.dimensions.width - room.wallHeight * 2 ) - room.box.width)) + room.wallHeight;
            room.box.y = Math.round(Math.random() * ((Renderer.dimensions.width - room.wallHeight * 2 ) - room.box.height)) + room.wallHeight;
        
            
            let doorPadding = constants.doorFrameThickness + constants.doorWidth/2 + constants.brickWidth/2;

            for(let wall = 0; wall<4; wall++){
                let oppositeWall = (wall + 2) % 4;
                let door = room.findDoor(wall);
                if (!door){
                    continue;
                }
                let neighbor = level.findNeighbor(room, wall);
                if(!neighbor.jittered){
                    continue;
                }
                
                let neighboringDoor = neighbor.findDoor(oppositeWall);
                
                let doorX = null;
                let doorY = null;
                let roomCenter = 0;
                let offset = 0;

                switch(wall){
                    case Direction.NORTH:
                        doorX = (-neighboringDoor.offset + neighbor.box.width/2 + neighbor.box.x + neighbor.wallHeight);
                        roomCenter = room.box.x + room.wallHeight + room.box.width/2;
                        offset = doorX - roomCenter;
    
                        if ((roomCenter + offset) < (room.box.x + room.wallHeight + doorPadding)){
                            let diff = ((room.box.x + room.wallHeight + doorPadding) - (roomCenter + offset));
                            let newleft = room.box.x - diff
                            offset += diff;
                            room.box.x = newleft;
                        }
                        if ((roomCenter + offset) > (room.box.x + room.wallHeight + room.box.width - doorPadding)){
                            let diff = (roomCenter + offset) -(room.box.x + room.wallHeight + room.box.width - doorPadding);
                            room.box.width +=diff;
                            roomCenter = room.box.x + room.wallHeight + room.box.width/2;
                            offset = doorX - roomCenter;
                        }
                        door.offset = offset;
                        break;
                    case Direction.WEST: 
                        doorY = (neighboringDoor.offset + neighbor.box.height/2 + neighbor.box.y + neighbor.wallHeight);
                        roomCenter = room.box.y + room.wallHeight + room.box.height/2;
                        offset = doorY - roomCenter;

                        if ((roomCenter + offset) < (room.box.y + room.wallHeight + doorPadding)){
                            let diff = ((room.box.y + room.wallHeight + doorPadding) - (roomCenter + offset));
                            let newtop = room.box.y - diff
                            offset += diff;
                            room.box.y = newtop;
                        }
                        if ((roomCenter + offset) > (room.box.y + room.wallHeight + room.box.height - doorPadding)){
                            let diff = (roomCenter + offset) -(room.box.y + room.wallHeight + room.box.height - doorPadding);
                            room.box.height +=diff;
                            roomCenter = room.box.y + room.wallHeight + room.box.height/2;                        
                            offset = doorY - roomCenter;
                        }
                        offset = offset *-1
                        
                        door.offset = offset;
                        break;
                    case Direction.SOUTH:
                        doorX = (neighboringDoor.offset + neighbor.box.width/2 + neighbor.box.x + neighbor.wallHeight);
                        roomCenter = room.box.x + room.wallHeight + room.box.width/2;
                        offset = doorX - roomCenter;

                        if ((roomCenter + offset) < (room.box.x + room.wallHeight + doorPadding)){
                            let diff = ((room.box.x + room.wallHeight + doorPadding) - (roomCenter + offset));
                            let newleft = room.box.x - diff
                            offset += diff;
                            room.box.x = newleft;
                        }
                        if ((roomCenter + offset) > (room.box.x + room.wallHeight + room.box.width - doorPadding)){
                            let diff = (roomCenter + offset) -(room.box.x + room.wallHeight + room.box.width - doorPadding);
                            room.box.width +=diff;
                            roomCenter = room.box.x + room.wallHeight + room.box.width/2;
                            offset = doorX - roomCenter;
                        }
                        offset = offset *-1
                        
                        door.offset = offset;
                        break;
                    case Direction.EAST: 
                        doorY = (-neighboringDoor.offset + neighbor.box.height/2 + neighbor.box.y + neighbor.wallHeight);
                        roomCenter = room.box.y + room.wallHeight + room.box.height/2;
                        offset = doorY - roomCenter;
                        if ((roomCenter + offset) < (room.box.y + room.wallHeight + doorPadding)){
                            let diff = ((room.box.y + room.wallHeight + doorPadding) - (roomCenter + offset));
                            let newtop = room.box.y - diff
                            offset += diff;
                            room.box.y = newtop;
                        }
                        if ((roomCenter + offset) > (room.box.y + room.wallHeight + room.box.height - doorPadding)){
                            let diff = (roomCenter + offset) -(room.box.y + room.wallHeight + room.box.height - doorPadding);
                            room.box.height +=diff;
                            roomCenter = room.box.y + room.wallHeight + room.box.height/2;
                            offset = doorY - roomCenter;    
                        }
                        
                        door.offset = offset;
                        break;
                }
            }
        }
    
        level.rooms.forEach((r)=>{
            r.doors.forEach((d)=>d.stabilize())
            r.finalize();
        });


        //log(exitRoom)
        //set exit
        let exit = new Exit(exitRoom);
        exit.box.center(exitRoom.box.center());
        //exitRoom.objects.push(exit);

        let startingRoom = level.rooms[0];
        let direction = !any(startingRoom.doors,(d)=>{return d.wall===Direction.NORTH}) ? Direction.NORTH :
                        !any(startingRoom.doors,(d)=>{return d.wall===Direction.EAST}) ? Direction.EAST :
                        !any(startingRoom.doors,(d)=>{return d.wall===Direction.WEST}) ? Direction.WEST :
                        Direction.SOUTH;


        let entranceDoor = new Door(level, startingRoom, direction, 0)
        entranceDoor.atmosphere = levelNumber % 5 == 0 ? "90-#000:50-#FFe:95" : "#000";
        entranceDoor.forceBars = true;
        entranceDoor.isEntrance = true;
        entranceDoor.stabilize();

        level.rooms[0].doors.push(entranceDoor);

        //pepper with keys
        for(let key = maxKey; key>Treasure.NONE; key--){
            let attemptCount = 0;
            let success = false;
            do {
                let keyroom = randomEntry(filter(level.rooms,(r,i)=>{return r.region < key && r.doors.length === 1 && !r.exit && !r.keyroom && i!=0 && !r.secret}));
                if (keyroom == null){
                    keyroom = randomEntry(filter(level.rooms,(r,i)=>{return r.region < key && !r.exit && !r.keyroom && i!=0 && !r.secret}));    
                }
                let chest = new TreasureChest(keyroom, key);
                success = keyroom &&  keyroom.spawn(chest);
                if(success){
                    keyroom.keyroom = true;
                }
                attemptCount++;
            } while (!success && attemptCount<100);
            if(!success){
                //this should never happen...
                return this.Construct(levelNumber);
            }
            level.statistics.keysSpawned++;
            level.statistics.chestsSpawned++;
        }
        
        //pepper with random treasure chests & enemies
        level.rooms.forEach((r,n)=>{
            if(r.secret){
                let failed = false;
                let count = 0
                do {
                    count++; 
                    let p = new Pickup(r, VC.Math.random(Treasure.HEART, Treasure.BEETLE), true);
                    failed = !r.spawn(p);
                }
                while(!failed && count<30);
            }
            if(n!==0 && !r.exit && !r.secret){
                let chests = VC.Math.random(r.spawnDensity-1, r.spawnDensity + 1)
            
                for(let i=0; i<chests; i++){
                    if (!r.keyroom && VC.Math.random(0,1)==1){
                        let spawned = r.spawn(new TreasureChest(r, Treasure.RANDOM));
                        if(spawned){
                            level.statistics.chestsSpawned++;        
                        }
                    }
                }
                if(chests === 0 && r.doors.length === 1 && !r.keyroom){
                    if (r.spawn(new TreasureChest(r, Treasure.RANDOM))){
                        level.statistics.chestsSpawned++;
                    }
                }

                //plant floor spikes

                r.doors.forEach((d)=>{
                    let x = 0;
                    let y = 0;
                    let fs1 = null;
                    let fs2 = null;
                    if(d instanceof SecretDoor){
                        return;
                    }
                    let offsetT = VC.Math.random(0,3000);
                    if(Math.random()<=.33){
                        new SpikeTrap(d, offsetT);
                    }
                });


            }
        })

        //initializeChests
        level.rooms.forEach((r)=>{
            filter(r.objects, (o)=>{return (o instanceof TreasureChest)}).forEach((t)=>{t.initialize();})
        });

        LevelFactory.getTemple(level.world).themeLevel(level)
        
        //add players
        let playerCounter = 1;
        
        server.players.forEach((player, playerid)=>{
            //log("playerId", playerid);
            player.spectating = playerid;
            var a = new Adventurer(level.rooms[0], player.controller);
            a.tag = "Server";
            //a.keys.push(Treasure.SILVERKEY);
            //a.id = playerid;
            player.gameObject = a;
            if (server.players.size>1){
                a.color = LevelFactory.getPlayerColor(playerCounter);
                playerCounter++;
            }
            level.players.set(playerid,player)
            level.rooms[0].spawn(a);//todo: spawn near entrance. Especially if single player.
            level.rooms[0].visited = 1;
        });
        return level;
    }

    static getPlayerColor(playerNumber){
        switch(playerNumber){
            case 1:
                return "#A00";
            case 2:
                return "#080";
            case 3:
                return "#FA0";
            case 4:
                return "#04F";
        }
    }

    
    static getTemple(worldNumber){
        switch(worldNumber){
            case 1:
                return new ForestTemple();
            case 2:
                return new FireTemple();
            case 3:
                return new WaterTemple();
            case 4:
                return new DesertTemple();
            case 5:
                return new IceTemple();
        }
        return null;
    }

    static getMusic(worldNumber){
            switch(worldNumber){
            case 1:
                return ForestTemple.music;
            case 2:
                return FireTemple.music;
            case 3:
                return WaterTemple().music;
            case 4:
                return DesertTemple().music;
            case 5:
                return IceTemple().music;
        }
        return null;    
    }

    static getWorldPalette(worldNumber){
        let worldPalette = [

            //World 1: Forest
            {    
                clipColor:"#19351A",
                floorColor: "#442A01",
                wallColor: "#505347"
            },
            //World 2: Fireplace
            {   
                clipColor:"#441910",
                floorColor: "#282424",
                wallColor: "#3f3c3c",
            }, 
            //World 3: Ocean
            {
                clipColor: '#3e6462', 
                floorColor: '#666563',
                wallColor: '#958f81'
            },
            //World 4: Desert
            {
                clipColor:"#642",
                wallColor: "#864",
                floorColor: "#753"
            }
        ]

        let paletteIndex = (worldNumber - 1) % worldPalette.length;
        return worldPalette[paletteIndex];
    }

    static hasOrphans(level, ignoreDoors){
        let queue = [level.rooms[0]];
        let visited = [];
        while(queue.length > 0){
            let room = queue.pop();
            room.doors.forEach((d)=>{
                if(ignoreDoors.indexOf(d) > -1){
                    return;
                }
                let n = level.findNeighbor(room, d.wall);
                if(visited.indexOf(n)===-1 && queue.indexOf(n)===-1){
                    queue.push(n);
                }
            });
            visited.push(room);
        }
        if(visited.length===level.rooms.length){
            return false;
        }
        return true;
    }
}
