window.onerror = function(message, source, lineNumber, colno, error) {
    if(!DEBUG){
            
        let body = encodeURI(`
        Send this email to help debug the issue!
        
        Message: ${message}
        
        Error: ${error}

        LineNumber: ${lineNumber}, ${colno}

        Call Stack:
        ${error.stack.replaceAll("https://goldruin.com/play/", "")}

        `);

        let uri = `mailto:Gold Ruin Developers<goldruindev@gmail.com>?subject=GoldRuin ${VERSION} Exception&body=${body}`

        if(confirm("Exception Found!\n\nWould you like to send this error to the developers?")){
            window.open(uri, "_self");
        }

    }
};

class EndLevelSummary extends RectangularRoom {
    sceneName = 'el';
    statistics = null;
    player = null;
    nextLevel = -1;
    number = -1;
    constructor(players){
        super(0, 0, 3 * constants.brickWidth, constants.roomMaxHeightInBricks * constants.brickWidth, 5 * constants.brickHeight,   new RectangularTileFloor(constants.tileWidth, constants.tileWidth));
        this.id = -1;
        if(players){
            this.players = players;
        }else{
            this.players = new Map();
        }
            
        this.volume = 1;
        this.box.x = this.wallHeight;
        this.box.y = Math.round((Renderer.dimensions.width - this.box.height - this.wallHeight*2) / 2) + this.wallHeight;
        if(game && game.level){
            this.palette = game.level.palette;
            this.palette.clipColor = SCREENBLACK;
        }
        
        let exit = new Exit(this)
        exit.box.x = this.box.center().x - exit.box.width / 2 ;
        exit.box.y = this.box.y + constants.doorFrameThickness;

        //exit.onTrip = function(){
            

        let entrance = new Door(null, this, Direction.SOUTH, 0);
        entrance.forceBars = true;
        this.doors.push(entrance);

  

        let wTorch = new Torch(this);
        wTorch.wall = Direction.WEST;
        wTorch.box.x = this.box.x - this.wallHeight / 2;
        wTorch.box.y = Renderer.dimensions.width * 2 / 3;
        
        let eTorch = new Torch(this);
        eTorch.wall = Direction.EAST;
        eTorch.box.x = this.box.x + this.box.width + this.wallHeight / 2;
        eTorch.box.y = Renderer.dimensions.width  / 3;
        
        this.finalize();
        this.doors.forEach((d)=>{d.stabilize()});
        this.secret = true;
    }
    preDisplay(){
        console.log("predisplay")
        renderer.playMusic(Music.EXIT_LEVEL);
        let world = Math.floor(this.number / 5) + 1;
        this.palette = LevelFactory.getWorldPalette(world);
        this.palette.clipColor = SCREENBLACK;
        if(this.nextLevel<5){
            this.floor = new HexagonalTileFloor(constants.tileWidth/2)
        }else if(this.nextLevel<10){
            this.floor = new StarTileFloor(58);
        }else{
        }
    }
    statsRendered = false
    preRender(deltaT){
        if(this.player && this.players){
            this.players.forEach((otherPlayer)=>{
                otherPlayer.spectating = this.player.clientId;
            });
        }
        if(this.player && this.player.gameObject){
            if(!this.initialized){

                this.player.room = this;
                this.player.gameObject.room = this;
                this.player.gameObject.box.x = this.box.center().x - this.player.gameObject.box.width/2;
                this.player.gameObject.box.y = this.box.height + this.box.y - this.wallHeight - this.player.gameObject.box.height;
                this.player.gameObject.direction = Direction.NORTH;
                this.player.gameObject.z = 0;
                //this.player.gameObject.speed = 150;
                this.initialized = true;

                let world = Math.floor(this.number / 5) + 1;
                console.log("world", world)
                var temple = LevelFactory.getTemple(world)
                this.palette = temple.palette;
                temple.themeRoom(this);
            }
            /*
            this.player.gameObject.sprite.lastLocation.x =  this.player.gameObject.box.x;
            this.player.gameObject.sprite.lastLocation.y = this.player.gameObject.box.y;
            this.player.gameObject.sprite.scale = 1;
            this.player.gameObject.sprite.location.z = 0;
            this.player.gameObject.sprite.lastLocation.z = 0;
            
            */

        }
        
        super.preRender(deltaT)
        

    }
    render(deltaT, screen){
        if(!this.statsRendered  && this.statistics){
            screen.drawRect(0,0,Renderer.dimensions.width, Renderer.dimensions.width, SCREENBLACK, SCREENBLACK, 0);
        }
        super.render(deltaT, screen)

        if(!this.statsRendered && this.statistics){
            let statsBox = new VC.Box(this.box.x + this.box.width + this.wallHeight, 0, Renderer.dimensions.width - (this.box.x + this.box.width + this.wallHeight), Renderer.dimensions.width);
            this.statistics.render(screen, "LEVEL COMPLETE!", statsBox);
            this.statsRendered = true
            
        }
    }

    getData(){
        let data = new Map();
        let p = []
        this.players.forEach((player)=>{
            p.push(player.getData())
        });
        this.sendStructure = true;
        this.players.forEach((player)=>{
            let playerData = {
                sceneName: this.sceneName,
                n: this.number,
                x: this.nextLevel,
                r: [super.getData()],
                p: p,
                l:this.player.clientId,
                s: this.statistics
            };

            let spectatingPlayer = this.players.get(player.spectating);
            
            if(spectatingPlayer.gameObject.state == State.DEAD && Date.now() - spectatingPlayer.gameObject._stateStart > 1500){
                //switch to a new player
                this.players.forEach((candidate)=>{
                    if(candidate && candidate.gameObject && candidate.gameObject.state != State.DEAD){
                        spectatingPlayer = candidate;
                    }
                });
            }
            player.spectating = spectatingPlayer.clientId

            data.set(player.clientId, playerData);
        });

        return data;
    }


    setData(data){
        if(data && data.sceneName==this.sceneName){
            if(this.number == -1){
                this.number = data.n;
            }
            if(this.nextLevel == -1){
                this.nextLevel = data.x;
            }
            if (data.r){
                super.setData(data.r[0]);
            }
            if (data.s && this.statistics == null){
                this.statistics = new Statistics()
                this.statistics.add(data.s);
            }
            if (data.p){
                //console.log(this.#players.length);
                let updated = [];
                data.p.forEach((player)=>{
                    let filteredPlayers = filter(this.players, (p)=>{return p.clientId == player.i});
                    if(filteredPlayers.length>1){
                        throw("wtf")
                    }
                    if(filteredPlayers.length == 0){
                        //new player, add them
                        let newPlayer = Player.fromData(player);
                        this.players.set(player.i, newPlayer)
                        updated.push(newPlayer)
                    }else{
                        filteredPlayers[0].setData(player)
                        updated.push(filteredPlayers[0]);
                    }
                });

            }
            this.player = filter(this.players, (p)=>{return p.clientId == data.l})[0];

        } else {
            console.warn (this.name, "ignored unexpected data:", JSON.stringify(data))
        }
    }

}

class GameModeScreen extends VC.Scene {
    #sceneName = "gm";
    #mode = 0;
    #peerType = 0;
    #menuPos = 0;
    #slideDir = 0;
    #slideStart = Date.now();
    #slideDuration = 666;
    #elements = [];
    #aStart = null;

    constructor(){
        super();      
    }
    get sceneName() {
        return this.#sceneName;
    }
    getData(){
        let obj =  {
            sceneName: this.#sceneName,
        }
        return obj;
    }
    setData(data){
        if(data && data.sceneName!=this.name){

        } else {
            console.warn (this.name, "ignored unexpected data:", JSON.stringify(data))
        }
    }
    lineGroup = null;
    hLines = [];
    adventurers = [];
    colorElements = [];
    singlePlayerElements = null;
    multiplayerElements = null;

    hostElements = null;
    joinElements = null;

    render(deltaT, screen){
        if(!this.structureRendered){
            this.#elements.push(screen.drawRect(0,0,Renderer.dimensions.width, Renderer.dimensions.width,	"#06402B",SCREENBLACK,0, 15));
            let text = screen.text(Renderer.dimensions.width/2,30, "CHOOSE YOUR DESTINY");
            text.attr({ "font-size": "40px", "font-family": "monospace", "fill": "#FFF", "font-weight": "bold"});
            this.#elements.push(text);  

            if(VC.System.orientation != VC.Orientation.PORTRAIT){
                text = screen.text(Renderer.dimensions.width/2,Renderer.dimensions.width-20, "ARROW KEYS TO CHOOSE, SPACE BAR TO SELECT, HOLD SPACE TO GO BACK");
                text.attr({ "font-size": "22px", "font-family": "monospace", "fill": "#FFF"});
                this.#elements.push(text);
            } else {
                text = screen.text(Renderer.dimensions.width/2,Renderer.dimensions.width-20, "HOLD FIRE TO GO BACK")
                text.attr({ "font-size": "24px", "font-family": "monospace", "fill": "#FFF"});
                this.#elements.push(text);
            }

            let box = screen.drawRect(Renderer.dimensions.width/2 - 150, 75, 300, 300,	"rgb(122, 85, 49)", "#FFF", 7, 15);
            let cliprect = screen.drawRect(Renderer.dimensions.width/2 - 146.5, 78.5, 292.5, 292.5,	"rgb(110, 75, 40)", SCREENBLACK,0, 15);

            this.lineGroup = screen.group();
            this.lineGroup.clipPath(cliprect);
            this.lineGroup.addElement(screen.drawLine(Renderer.dimensions.width/2 + 50, 75, Renderer.dimensions.width/2 + 55, 375,SCREENBLACK, 3).attr({'opacity': .25}))
            this.lineGroup.addElement(screen.drawLine(Renderer.dimensions.width/2 - 50, 75, Renderer.dimensions.width/2 - 55, 375,SCREENBLACK, 3).attr({'opacity': .25}))

            for(let i = 0; i<4; i++){
                let line = screen.drawLine(Renderer.dimensions.width/2 - 150, 75 + ((i+1) * 75), Renderer.dimensions.width/2 + 150, 75 + ((i+1) * 75), SCREENBLACK, 2).attr({'opacity': .25})
                this.hLines.push(line);
                this.lineGroup.addElement(line);
            }

            this.createAdventurer(screen, Renderer.dimensions.width/2, 225, LevelFactory.getPlayerColor(4));
            this.createAdventurer(screen, Renderer.dimensions.width/2-60, 265, LevelFactory.getPlayerColor(2));
            this.createAdventurer(screen, Renderer.dimensions.width/2+60, 265, LevelFactory.getPlayerColor(3));
            this.createAdventurer(screen, Renderer.dimensions.width/2, 300, LevelFactory.getPlayerColor(1));

            this.singlePlayerElements = this.createButton(screen, 450, 0, "Venture Forth Alone");
            this.multiplayerElements = this.createButton(screen, 650, 1, "Explore Together");

            this.hostElements = this.createButton(screen, 450, 2, "Assemble a Party");
            this.joinElements = this.createButton(screen, 650, 3, "Join an Expedition");

            this.slide(this.hostElements, Renderer.dimensions.width);
            this.slide(this.joinElements, Renderer.dimensions.width);

            this.structureRendered = true;
        }

        this.hLines.forEach((line)=>{
            let attr = line.attr();
            let y = attr.path[0][2];
            y -=1;
            if(y<75){
                y = 75 * 5;
            }
            attr.path[0][2] = y;
            attr.path[1][2] = y;

            line.attr(attr);
        })

        if(this.#mode==1){
            this.deactivateButton(this.singlePlayerElements);
            this.activateButton(this.multiplayerElements);
            this.colorElements.forEach((el,i)=>{
                if(i % 2 == 0 ){
                    el.attr({opacity: .33});
                }else {
                    el.attr({opacity: .5});
                }
            });
            this.adventurers.forEach((s,i)=>{
                s.opacity=1;
            });
        }else{
            this.deactivateButton(this.multiplayerElements);
            this.activateButton(this.singlePlayerElements);
            this.colorElements.forEach((el,i)=>{
                el.attr({opacity: 0});
            });
            this.adventurers.forEach((s,i)=>{
                if(i!=3){
                    s.opacity=0;
                }
            });
        }

        if(this.#peerType==1){
            this.deactivateButton(this.hostElements);
            this.activateButton(this.joinElements);
        }else{
            this.deactivateButton(this.joinElements);
            this.activateButton(this.hostElements);
        }

        if(renderer && renderer.inputController){
            let shuffle = false;
            let beep = false;
            let boop = false;
            let back = false;
            let forward = false;
            let input = renderer.inputController.read();
            if(input.a && this.aReady){
                if(this.#aStart == null){
                    this.#aStart = Date.now();
                }else{
                    if(Date.now() - this.#aStart>500){
                        back = true;
                    }
                }
            } else if (!input.a){
                this.aReady = true;
                if(this.#aStart != null){
                    if(Date.now() - this.#aStart<=500){
                        forward = true;
                    }
                }
                this.#aStart = null;
            }
            if(forward){
                shuffle = true;
                if(this.#mode==0){
                    GameLauncher.launchSinglePlayer()
                } else if(this.#menuPos == 0){
                    this.#slideDir = -1;
                    this.#slideStart = Date.now();
                } else {
                    if(this.#peerType == 0){
                        GameLauncher.startHost()
                    }else {
                        renderer.currentScene = new JoinLobbyScreen();
                    }
                }
            }else if(back){
                if(this.#menuPos==0){
                    renderer.currentScene = new SlotSelectScreen();
                } else if (this.#slideDir == 0){
                    shuffle = true;
                    this.#slideDir = 1;
                    this.#slideStart = Date.now();
                } 
            } else if(input.y != 0){
                if(this.#menuPos==0 && input.y == -1 && this.#mode != 0 ){
                    boop = true;
                    this.#mode = 0;
                } else if(this.#menuPos==0 && input.y == 1 && this.#mode != 1 ){
                    beep = true;
                    this.#mode = 1;
                } else if(this.#menuPos!=0 && input.y == -1 && this.#peerType != 0 ){
                    boop = true;
                    this.#peerType = 0;
                } else if(this.#menuPos!=0 && input.y == 1 && this.#peerType != 1 ){
                    beep = true;
                    this.#peerType = 1;
                }
            }
            if(shuffle){
                renderer.audioChannel.play(SoundEffects.TNT.data, .4, false);
            }else if (boop){
                renderer.audioChannel.play(SoundEffects.KEY_BOOP.data, .2, false);
            }else if (beep){
                renderer.audioChannel.play(SoundEffects.KEY_BEEP.data, .2, false);
            }
        }

        

        if(this.#slideDir!=0){
            let perc = VC.Math.constrain(0,(Date.now()-this.#slideStart)/this.#slideDuration, 1);

            if(this.#slideDir == -1){
                this.#menuPos = VC.Math.inversePercentToRange(perc, -Renderer.dimensions.width, 0);
            }else {
                this.#menuPos = VC.Math.percentToRange(perc, -Renderer.dimensions.width, 0);    
            }
            this.slide(this.singlePlayerElements, this.#menuPos);
            this.slide(this.multiplayerElements,  this.#menuPos);


            this.slide(this.hostElements, Renderer.dimensions.width + this.#menuPos);
            this.slide(this.joinElements, Renderer.dimensions.width + this.#menuPos);
            if(perc==1){
                this.#slideDir = 0;
            }
        }

        this.adventurers.forEach((adv)=>{
            adv.render(deltaT)
        })

        renderer.playMusic(Music.CHARGE);
    }

    createAdventurer(screen, x,y,color){
        
            let advColorElement1;
            let advColorElement2;
            
            advColorElement1 = screen.drawEllipse(0, 0, 30, 15, 0, 0, null, color, 12);
            advColorElement1.attr({opacity: .33});
            advColorElement2 = screen.drawEllipse(0, 0, 30, 15, 0, 0, null, color, 4);
            advColorElement2.attr({opacity: .5});
            
            let attr = {
                cx: x, 
                cy: y
            }
            advColorElement1.attr(attr);
            advColorElement2.attr(attr);
            advColorElement1.toFront();
            advColorElement2.toFront();
            this.colorElements.push(advColorElement1);
            this.colorElements.push(advColorElement2);
            let adventurer1 =  new VC.Sprite(screen, Images.ADVENTURER, 800, 600, 100, 100, x-50, y-95);
            adventurer1.setAnimation(2,1);
            
            this.adventurers.push(adventurer1);
    
    }

    createButton(screen, y, iconIndex, message){
        let elements = []
        elements.push(screen.drawRect(50, y, Renderer.dimensions.width-100, 168, SCREENBLACK, null , 0, 25).attr({"opacity":.25}));
        elements.push(screen.drawLine(226, y, 226, y+168, SCREENBLACK, 10))
        elements.push(screen.drawRect(50, y, Renderer.dimensions.width-100, 168, null, SCREENBLACK, 3, 25).attr({"opacity":.5}));
        

        let text = screen.text(276,y+80, message);
        text.attr({ "font-size": "46px", "font-family": "monospace", "fill": "#FFF","text-anchor": "start", "opacity":.5});
        elements.push(text); 

        let sprite = new VC.Sprite(screen, Images.MENU_ICONS, 128, 512, 128, 128, 74, y+16);
        sprite.opacity = .5;
        sprite.setFrame(0,iconIndex,0);
        sprite.render();
        elements.push(sprite);
        return elements;
    }

    activateButton(elements){
        elements[0].attr({"fill":"#cff", opacity: .1});
        elements[1].attr({"stroke":"#EA0", opacity: 1});
        elements[2].attr({"stroke":"#FFF", opacity: 1});
        elements[3].attr({opacity: .9});
        elements[4].opacity = 1;
        elements[4].render();
    }

    deactivateButton(elements){

        elements[0].attr({"fill":SCREENBLACK, opacity: .25});
        elements[1].attr({"stroke": SCREENBLACK, opacity: .5});
        elements[2].attr({"stroke": SCREENBLACK});
        elements[3].attr({opacity: .5});
        elements[4].opacity = .5;
        elements[4].render();

    }

    slide(elements, newX){
        elements.forEach((el)=>{
            if(el instanceof VC.Sprite){
                el.location.x = newX + 74;
                el.render();
            } else {
                el.transform("t" + newX + ",0");
            }
        });
    }

}
class LobbyScreen_PlayerDisplay{
    playerName = "";
    constructor(playerData){
        this.playerName = playerData.n;
        this.ready = false;
    }

    #ready = false;
    get ready(){
        return this.#ready;
    }
    set ready(value){
        if(this.statusText){
            if(value){
                this.statusText.attr({text:"Ready!"});
            }else{
                this.statusText.attr({text:"Not Ready"});
            }
        }
        this.#ready = value;
    }
    
    
    #y = Renderer.dimensions.width;
    get y(){
        return this.#y
    }
    set y(value){
        if(this.#y!=value){
            this.#y = value;
            if(this.background){
                this.background.attr({y: value});
            }
            if(this.advFrame){
                this.advFrame.attr({y: value + 5});
            }
            if(this.advColorElement1){
                this.advColorElement1.attr({cy: value + 120});
            }
            if(this.advColorElement2){
                this.advColorElement2.attr({cy: value + 120});
            }
            if(this.playerNameDisplay){
                this.playerNameDisplay.attr({y: value + 40});
            }
            if(this.statusText){
                this.statusText.attr({y: value + 130});
            }
            if(this.sprite){
                this.sprite.location.y = value + 25;
            }
        }
    }

    #targetY = 0;
    get targetY(){
        return this.#targetY
    }
    set targetY(value){
        if(this.#targetY!=value){
            this.#targetY = value;
            this.targetYSet = Date.now();
            this.startY = this.#y;
        }
    }
      
    #x = 0;
    get x(){
        return this.#x
    }
    set x(value){
        if(this.#x!=value){
            this.#x = value;
            if(this.background){
                this.background.attr({x: value + 50});
            }
            if(this.advFrame){
                this.advFrame.attr({x: value + 55});
            }
            if(this.advColorElement1){
                this.advColorElement1.attr({cx: value + 125});
            }
            if(this.advColorElement2){
                this.advColorElement2.attr({cx: value + 125});
            }
            if(this.playerNameDisplay){
                this.playerNameDisplay.attr({x: value + 225});
            }
            if(this.statusText){
                this.statusText.attr({x: value + (Renderer.dimensions.width - 60)});
            }
            if(this.sprite){
                this.sprite.location.x = value + 75;
            }
        }
    }
    

    #playerNumber = 1;
    get playerNumber(){
        return this.#playerNumber;
    }
    set playerNumber(value){
        //todo: change color elements
        if (value!=this.#playerNumber){
            this.#playerNumber = value;
            let color = LevelFactory.getPlayerColor(this.#playerNumber);
            if(this.advColorElement1){
                this.advColorElement1.attr({"stroke": color});
            }
            if(this.advColorElement2){
                this.advColorElement2.attr({"stroke": color});
            }
            if(this.advFrame){
                this.advFrame.attr({"stroke": color});
            }
        }
    }
    background = null;
    advFrame = null;
    advColorElement1 = null;
    advColorElement2 = null;
    playerNameDisplay = null;
    sprite = null;
    render(deltaT, screen){
        if(!this.structureRendered){
            this.background = screen.drawRect(50,this.y,Renderer.dimensions.width-100, 150, "#333", "#fff", 3, 15).attr({opacity:.5});
            this.advFrame = screen.drawRect(55,this.y+5,140, 140, "rgb(122, 85, 49)",  LevelFactory.getPlayerColor(this.playerNumber), 5, 15);
            //this.statusFrame = screen.drawRect(Renderer.dimensions.width-198, this.y+119, 150, 30, "#000", null, 0, 15).attr({opacity:.5})
            this.advColorElement1 = screen.drawEllipse(125, this.y + 120, 30, 15, 0, 0, null, LevelFactory.getPlayerColor(this.playerNumber), 12);
            this.advColorElement1.attr({opacity: .33});
            this.advColorElement2 = screen.drawEllipse(125, this.y + 120, 30, 15, 0, 0, null, LevelFactory.getPlayerColor(this.playerNumber), 4);
            this.advColorElement2.attr({opacity: .5});
            this.playerNameDisplay = screen.text(225, this.y + 40, this.playerName);
            this.playerNameDisplay.attr({ "font-size": "40px", "font-family": "monospace", "fill": "#FFF", "font-weight": "bold", "text-anchor": "start"});
            
            this.statusText = screen.text(Renderer.dimensions.width - 60, this.y + 130, "Not Ready");
            this.statusText.attr({ "font-size": "25px", "font-family": "monospace", "fill": "#FFF", "font-weight": "bold", "text-anchor": "end"});
            
            this.sprite = new VC.Sprite(screen, Images.ADVENTURER, 800, 600, 100, 100, 75, this.y + 25);
            this.sprite.setAnimation(2,1);
            this.structureRendered = true;
        }
        if(this.removeStart){
            this.x = VC.Math.percentToRange((Date.now()-this.removeStart)/800, 0, Renderer.dimensions.width);
        }
        if(this.targetYSet && this.targetY<this.y){
            this.y = VC.Math.inversePercentToRange((Date.now()-this.targetYSet)/1000, this.targetY, this.startY);
        }
        this.background.toFront();
        this.advFrame.toFront();
        this.advColorElement1.toFront();
        this.advColorElement2.toFront();
        this.playerNameDisplay.toFront();
        this.statusText.toFront();
        
        this.sprite.render(deltaT);
    }
    addToGroup(group){
       // if(!this.addedToGroup){
            this.addedToGroup = true;
            group.addElement(
                this.background,
                this.advFrame,
                this.advColorElement1,
                this.advColorElement2,
                this.playerNameDisplay,
                this.statusText,
                this.sprite.element
            );
        //}
    }
    remove(){
        if(!this.removeStart){
            this.removeStart = Date.now();
            this.background.attr({"stroke": "#F00"})
        }
        if(!this.removed && this.x > Renderer.dimensions.width - 50){
            this.removed = true;
            this.sprite.remove();
            this.background.remove();
            this.advFrame.remove();
            this.advColorElement1.remove();
            this.advColorElement2.remove();
            this.playerNameDisplay.remove();
            this.statusText.remove();
        }
    }
}
class LobbyScreen extends VC.Scene {
    #sceneName = "lb";
    #elements = [];
    #joinCode = "";
    #players = [];

    constructor(){
        super();      
    }
    get sceneName() {
        return this.#sceneName;
    }
    getData(){
        let obj =  {
            sceneName: this.#sceneName,
            j: this.#joinCode,
            p: this.#players
        }
        return obj;
    }
    setData(data){
        if(data && data.sceneName==this.sceneName){
            this.#joinCode = data.j;
            this.#players = data.p;
        } else {
            console.warn (this.name, "ignored unexpected data:", JSON.stringify(data))
        }
    }
    readyPlayers = [];
    exitingPlayers = [];

    aHandled = [];
    holdStart = new Map()
    preRender(){
        if(server){
            this.#joinCode = server.id
            //console.log(server.id);
            this.#players = [];
            if(server.players.size<2){
                this.readyPlayers.length = 0;
            }
            server.players.forEach((player, playerId)=>{
                let input = player.controller.read();
                if(input){
                    if(input.a){
                        if(!this.holdStart.has(playerId)){
                            this.holdStart.set(playerId, Date.now())
                        }
                        let holdLength = Date.now()-this.holdStart.get(playerId);
                        if(holdLength>400){
                            this.holdStart.set(playerId, Date.now()+10000000);
                            if(this.exitingPlayers.indexOf(playerId)==-1){
                                this.exitingPlayers.push(playerId);
                            } 
                        } 
                    } else if(this.holdStart.has(playerId)){
                        let holdLength = Date.now()-this.holdStart.get(playerId);
                        this.holdStart.delete(playerId);
                        if(holdLength>0 && holdLength<=400 && server.players.size>1 && this.readyPlayers.indexOf(playerId)==-1 && this.exitingPlayers.indexOf(playerId)==-1){
                            this.readyPlayers.push(playerId);
                        }else  if(holdLength>0 && holdLength<=400  && this.readyPlayers.indexOf(playerId)!=-1 && this.exitingPlayers.indexOf(playerId)==-1){
                            this.readyPlayers.splice(this.readyPlayers.indexOf(playerId),1);
                        }
                    }
                }
                
                this.#players.push({i: playerId, n:player.playerName, r:this.readyPlayers.indexOf(playerId)!=-1, x:this.exitingPlayers.indexOf(playerId)!=-1});
            })
            if(this.readyPlayers.length == server.players.size){
                //todo: start game
                game.currentScene = new LevelSelectScreen();
            }
        }
    }
    #playerDisplayGroup = null;
    #playerDisplays = new Map();
    #waitText = null;
    render(deltaT, screen){
        
        if(!this.structureRendered){
            this.#elements.push(screen.drawRect(0,0,Renderer.dimensions.width, Renderer.dimensions.width,	"#06402B",SCREENBLACK,0, 15));
            this.#elements.push(screen.drawRect(Renderer.dimensions.width/2 - 125,68,250, 100,	SCREENBLACK,"#FFF",3, 15).attr({opacity: .33}));
            this.#elements.push(screen.drawRect(50,225,Renderer.dimensions.width-100, 600,	SCREENBLACK,"#FFF",5, 15).attr({opacity: .33}));
            
            this.#playerDisplayGroup = screen.group();
            this.#playerDisplayGroup.clipPath(screen.drawRect(50,225,Renderer.dimensions.width-100, 600,SCREENBLACK,"#FFF",3, 15))

            let text = screen.text(Renderer.dimensions.width/2,30, "JOIN CODE: ");
            text.attr({ "font-size": "40px", "font-family": "monospace", "fill": "#FFF", "font-weight": "bold"});
            text = screen.text(Renderer.dimensions.width/2,120, this.#joinCode);
            text.attr({ "font-size": "75px", "font-family": "monospace", "fill": "#EA0", "stroke": "#A80", "stroke-width": 3, "font-weight": "bold"});
            
            if(VC.System.orientation != VC.Orientation.PORTRAIT){
                text = screen.text(Renderer.dimensions.width/2,Renderer.dimensions.width-20, "TAP SPACE WHEN READY, HOLD SPACE TO QUIT")
                text.attr({ "font-size": "24px", "font-family": "monospace", "fill": "#FFF"});
            } else {
                text = screen.text(Renderer.dimensions.width/2,Renderer.dimensions.width-20, "TAP FIRE WHEN READY, HOLD FIRE TO QUIT")
                text.attr({ "font-size": "24px", "font-family": "monospace", "fill": "#FFF"});
            }

            this.waitText = screen.text(Renderer.dimensions.width/2,790, "Waiting...");
            this.waitText.attr({ "font-size": "35px", "font-family": "monospace", "fill": "#FFF"});

            this.structureRendered = true;
        }

        this.#players.forEach((p, i)=>{
            if(!this.#playerDisplays.has(p.i)){
                this.#playerDisplays.set(p.i, new LobbyScreen_PlayerDisplay(p));
            }   
            this.#playerDisplays.get(p.i).ready = p.r; 
            if(p.i == client.id && p.x){
                client.disconnect();
                client = new Client();
                if(i == 0 ){
                    //we're the host. shut down. 
                    server.stop();
                    server = null;
                }
                renderer.currentScene = new GameModeScreen();
            }
        });
        //todo: copy to level
        if(!client.isConnected){
            client = new Client();
            renderer.currentScene = new GameModeScreen();
        }
        let n = 1;
        //Todo: remove dropped players.
        let removeThese = [];
        this.#playerDisplays.forEach((v,key)=>{
            if(!any(this.#players, (p)=>{return p.i == key})){
                v.remove();
                if(v.removed){
                    removeThese.push(key);
                }
            }
        });
        removeThese.forEach((key)=>{this.#playerDisplays.delete(key)});
        this.#playerDisplays.forEach((playerDisplay)=>{
            playerDisplay.playerNumber = n;
            playerDisplay.targetY = 225 + ((n-1) * 150);
            playerDisplay.render(deltaT, screen);
            playerDisplay.addToGroup(this.#playerDisplayGroup);
            n++;
        });

        if(this.#playerDisplays.size<2){
            let pulse = Date.now() % 3000;
            if(pulse <1500){
                this.waitText.attr({opacity: pulse/1500 });
            } else {
                pulse = pulse - 1500
                this.waitText.attr({opacity:  1-pulse/1500 });
            }
        }else{
            this.waitText.attr({opacity:  0 });    
        }
        //this.joinText.attr({"text ":"JOIN CODE: " + this.#joinCode})
        //renderer.playMusic(Music.CHARGE);
    }


}
